caliptra_sram #(
    .DEPTH     (32768 / (64/8)     ),  
    .DATA_WIDTH(64),
    .ADDR_WIDTH($clog2(32768 / (64/8)))
) imem_inst1 (
    .clk_i   (clk   ),
    .cs_i    (imem_cs),
    .we_i    (1'b0       ),
    .addr_i  (imem_addr                          ),
