     .DEPTH     (16384        ),  
     .DATA_WIDTH(64           ),
     .ADDR_WIDTH($clog2(16384))
) dummy_iccm_preloader (
    .clk_i   (clk),
    .cs_i    (        ),
    .we_i    (        ),
    .addr_i  (        ),
    .wdata_i (        ),
    .rdata_o (        )
);
caliptra_sram #(
     .DEPTH     (16384        ),  
     .DATA_WIDTH(64           ),
     .ADDR_WIDTH($clog2(16384))
) dummy_dccm_preloader (
    .clk_i   (clk),
    .cs_i    (        ),
    .we_i    (        ),
    .addr_i  (        ),
    .wdata_i (        ),
    .rdata_o (        )
