   input logic [pt.DCCM_FDATA_WIDTH-1:0]  dccm_wr_data_hi,
   output logic [pt.DCCM_FDATA_WIDTH-1:0]  dccm_rd_data_lo,
   output logic [pt.DCCM_FDATA_WIDTH-1:0]  dccm_rd_data_hi,
   input logic [pt.ICCM_BITS-1:1]  iccm_rw_addr,
   input logic                                        iccm_buf_correct_ecc,                     
   input logic                                        iccm_correction_state,                
   input logic         iccm_wren,
   input logic         iccm_rden,
   input logic [2:0]   iccm_wr_size,
   input logic [77:0]  iccm_wr_data,
   output logic [63:0] iccm_rd_data,
   output logic [77:0] iccm_rd_data_ecc,
   input  logic [31:1]  ic_rw_addr,
   input  logic [pt.ICACHE_NUM_WAYS-1:0]   ic_tag_valid,
   input  logic [pt.ICACHE_NUM_WAYS-1:0]   ic_wr_en,
   input  logic         ic_rd_en,
   input  logic [63:0] ic_premux_data,       
   input  logic         ic_sel_premux_data,  
   input  logic [pt.ICACHE_BANKS_WAY-1:0][70:0]               ic_wr_data,          
   input  logic [70:0]               ic_debug_wr_data,    
   output logic [70:0]               ic_debug_rd_data ,   
   input  logic [pt.ICACHE_INDEX_HI:3]               ic_debug_addr,       
   input  logic                      ic_debug_rd_en,      
   input  logic                      ic_debug_wr_en,      
   input  logic                      ic_debug_tag_array,  
   input  logic [pt.ICACHE_NUM_WAYS-1:0]                ic_debug_way,        
   output logic [63:0]              ic_rd_data ,         
   output logic [25:0]               ictag_debug_rd_data, 
   output logic [pt.ICACHE_BANKS_WAY-1:0] ic_eccerr,     
   output logic [pt.ICACHE_BANKS_WAY-1:0] ic_parerr,           
   output logic [pt.ICACHE_NUM_WAYS-1:0]   ic_rd_hit,
   output logic         ic_tag_perr,         
   el2_mem_if           mem_export,
   input  logic         scan_mode
);
   logic active_clk;
   rvoclkhdr active_cg   ( .en(1'b1),         .l1clk(active_clk), .* );
   if (pt.DCCM_ENABLE == 1) begin: Gen_dccm_enable
      el2_lsu_dccm_mem #(.pt(pt)) dccm (
         .clk_override(dccm_clk_override),
         .dccm_mem_export(mem_export.veer_dccm),
         .*
      );
   end else begin: Gen_dccm_disable
      assign dccm_rd_data_lo = '0;
      assign dccm_rd_data_hi = '0;
   end
if ( pt.ICACHE_ENABLE ) begin: icache
   el2_ifu_ic_mem #(.pt(pt)) icm  (
      .clk_override(icm_clk_override),
      .*
   );
end
else  begin
   assign   ic_rd_hit[pt.ICACHE_NUM_WAYS-1:0] = '0;
   assign   ic_tag_perr    = '0 ;
   assign   ic_rd_data  = '0 ;
   assign   ictag_debug_rd_data  = '0 ;
end  
if (pt.ICCM_ENABLE) begin : iccm
   el2_ifu_iccm_mem  #(.pt(pt)) iccm (.*,
                  .clk_override(icm_clk_override),
                  .iccm_rw_addr(iccm_rw_addr[pt.ICCM_BITS-1:1]),
                  .iccm_rd_data(iccm_rd_data[63:0]),
                  .iccm_mem_export(mem_export.veer_iccm)
                   );
end
else  begin
   assign  iccm_rd_data    = '0 ;
   assign iccm_rd_data_ecc = '0 ;
end
