   assign i0_wb_en                   =  i0_wb_data_en;
   assign i0_inst_wb_in[31:0]        =  i0_inst_r[31:0];
   assign i0_inst_d[31:0]            = (dec_i0_pc4_d)    ?  i0[31:0]                                  :  {16'b0, ifu_i0_cinst[15:0]};
   assign trace_enable = ~dec_tlu_trace_disable;
