   input logic       ifu_i0_valid,                                  
   input logic       ifu_i0_icaf,                                   
   input logic [1:0] ifu_i0_icaf_type,                              
   input logic   ifu_i0_icaf_second,                                
   input logic   ifu_i0_dbecc,                                      
   input logic [31:0]  ifu_i0_instr,                                
   input logic [31:1]  ifu_i0_pc,                                   
   output logic dec_ib0_valid_d,                                    
   output logic dec_debug_valid_d,                                  
   output logic [31:0] dec_i0_instr_d,                              
   output logic [31:1] dec_i0_pc_d,                                 
   output logic dec_i0_pc4_d,                                       
   output el2_br_pkt_t dec_i0_brp,                                 
   output logic [pt.BTB_ADDR_HI:pt.BTB_ADDR_LO] dec_i0_bp_index,    
   output logic [pt.BHT_GHR_SIZE-1:0] dec_i0_bp_fghr,               
   output logic [pt.BTB_BTAG_SIZE-1:0] dec_i0_bp_btag,              
   output logic [$clog2(pt.BTB_SIZE)-1:0] dec_i0_bp_fa_index,           
   output logic dec_i0_icaf_d,                                      
   output logic dec_i0_icaf_second_d,                               
   output logic [1:0] dec_i0_icaf_type_d,                           
   output logic dec_i0_dbecc_d,                                     
   output logic dec_debug_wdata_rs1_d,                              
   output logic dec_debug_fence_d                                   
   );
   logic         debug_valid;
   logic [4:0]   dreg;
   logic [11:0]  dcsr;
   logic [31:0]  ib0, ib0_debug_in;
   logic         debug_read;
   logic         debug_write;
   logic         debug_read_gpr;
   logic         debug_write_gpr;
   logic         debug_read_csr;
   logic         debug_write_csr;
   logic [34:0]  ifu_i0_pcdata, pc0;
   assign ifu_i0_pcdata[34:0] = { ifu_i0_icaf_second, ifu_i0_dbecc, ifu_i0_icaf,
                                  ifu_i0_pc[31:1], ifu_i0_pc4 };
   assign pc0[34:0] = ifu_i0_pcdata[34:0];
   assign dec_i0_icaf_second_d = pc0[34];    
   assign dec_i0_dbecc_d = pc0[33];
   assign dec_i0_icaf_d = pc0[32];
   assign dec_i0_pc_d[31:1] = pc0[31:1];
   assign dec_i0_pc4_d = pc0[0];
   assign dec_i0_icaf_type_d[1:0] = ifu_i0_icaf_type[1:0];
   assign debug_valid = dbg_cmd_valid & (dbg_cmd_type[1:0] != 2'h2);
   assign debug_read  = debug_valid & ~dbg_cmd_write;
   assign debug_write = debug_valid &  dbg_cmd_write;
   assign debug_read_gpr  = debug_read  & (dbg_cmd_type[1:0]==2'h0);
   assign debug_write_gpr = debug_write & (dbg_cmd_type[1:0]==2'h0);
   assign debug_read_csr  = debug_read  & (dbg_cmd_type[1:0]==2'h1);
   assign debug_write_csr = debug_write & (dbg_cmd_type[1:0]==2'h1);
   assign dreg[4:0]  = dbg_cmd_addr[4:0];
   assign dcsr[11:0] = dbg_cmd_addr[11:0];
   assign ib0_debug_in[31:0] = ({32{debug_read_gpr}}  & {12'b000000000000,dreg[4:0],15'b110000000110011}) |
                               ({32{debug_write_gpr}} & {20'b00000000000000000110,dreg[4:0],7'b0110011}) |
                               ({32{debug_read_csr}}  & {dcsr[11:0],20'b00000010000001110011}) |
                               ({32{debug_write_csr}} & {dcsr[11:0],20'b00000001000001110011});
   assign dec_debug_wdata_rs1_d = debug_write_gpr | debug_write_csr;
   assign dec_debug_fence_d = debug_write_csr & (dcsr[11:0] == 12'h7c4);
   assign ib0[31:0] = (debug_valid) ? ib0_debug_in[31:0] : ifu_i0_instr[31:0];
   assign dec_ib0_valid_d = ifu_i0_valid | debug_valid;
   assign dec_debug_valid_d = debug_valid;
   assign dec_i0_instr_d[31:0] = ib0[31:0];
   assign dec_i0_brp = i0_brp;
   assign dec_i0_bp_index = ifu_i0_bp_index;
   assign dec_i0_bp_fghr = ifu_i0_bp_fghr;
   assign dec_i0_bp_btag = ifu_i0_bp_btag;
   assign dec_i0_bp_fa_index = ifu_i0_fa_index;
endmodule
