  (
   input  logic                  clk,                 
   input  logic                  rst_l,               
   input  logic                  scan_mode,           
   input  logic                  flush_upper_x,       
   input  logic                  flush_lower_r,       
   input  logic                  enable,              
   input  logic                  valid_in,            
   input  el2_alu_pkt_t         ap,                  
   input  logic                  csr_ren_in,          
   input  logic        [31:0]    csr_rddata_in,       
   input  logic signed [31:0]    a_in,                
   input  logic        [31:0]    b_in,                
   input  logic        [31:1]    pc_in,               
   input  el2_predict_pkt_t     pp_in,               
   input  logic        [12:1]    brimm_in,            
   output logic        [31:0]    result_ff,           
   output logic                  flush_upper_out,     
   output logic                  flush_final_out,     
   output logic        [31:1]    flush_path_out,      
   output logic        [31:1]    pc_ff,               
   output logic                  pred_correct_out,    
   output el2_predict_pkt_t     predict_p_out        
  );
   logic               [31:0]    zba_a_in;
   logic               [31:0]    aout;
   logic                         cout,ov,neg;
   logic               [31:0]    lout;
   logic               [31:0]    sout;
   logic                         sel_shift;
   logic                         sel_adder;
   logic                         slt_one;
   logic                         actual_taken;
   logic               [31:1]    pcout;
   logic                         cond_mispredict;
   logic                         target_mispredict;
   logic                         eq, ne, lt, ge;
   logic                         any_jal;
   logic               [1:0]     newhist;
   logic                         sel_pc;
   logic               [31:0]    csr_write_data;
   logic               [31:0]    result;
   logic                  ap_clz;
   logic                  ap_ctz;
   logic                  ap_cpop;
   logic                  ap_sext_b;
   logic                  ap_sext_h;
   logic                  ap_min;
   logic                  ap_max;
   logic                  ap_rol;
   logic                  ap_ror;
   logic                  ap_rev8;
   logic                  ap_orc_b;
   logic                  ap_zbb;
   logic                  ap_bset;
   logic                  ap_bclr;
   logic                  ap_binv;
   logic                  ap_bext;
   logic                  ap_pack;
   logic                  ap_packu;
   logic                  ap_packh;
   logic                  ap_sh1add;
   logic                  ap_sh2add;
   logic                  ap_sh3add;
   logic                  ap_zba;
   if (pt.BITMANIP_ZBB == 1)
     begin
       assign ap_clz          =  ap.clz;
       assign ap_ctz          =  ap.ctz;
       assign ap_cpop         =  ap.cpop;
       assign ap_sext_b       =  ap.sext_b;
