   input logic [$clog2(512)-1:0] ADR,     
   input logic [(88-1):0] D, WEM,        
   output logic [(88-1):0] Q,            
input logic WE,              
input logic ME,              
input logic CLK,             
input logic TEST1,           
input logic RME,             
input logic  [3:0] RM,       
input logic LS,              
input logic DS,              
input logic SD,              
input logic TEST_RNM,        
input logic BC1,             
input logic BC2,             
output logic ROP                 
);                                          
reg [(88-1):0] ram_core [(512-1):0];   
always @(posedge CLK) begin                 
   if (ME && WE) begin ram_core[ADR] <= D & WEM | ~WEM & ram_core[ADR]; Q <= 'x; end  
   if (ME && ~WE) Q <= ram_core[ADR];          
end                                         
assign ROP = ME;                            
endmodule
