   input logic      clk_override,                       
   input logic      dma_dccm_req,                       
   input logic      ldst_stbuf_reqvld_r,                
   input logic      stbuf_reqvld_any,                   
   input logic      stbuf_reqvld_flushed_any,           
   input logic      lsu_busreq_r,                       
