   output logic [pt.DCCM_DATA_WIDTH-1:0]   dccm_rdata_hi_m,          
   output logic [pt.DCCM_DATA_WIDTH-1:0]   dccm_rdata_lo_m,          
   output logic [pt.DCCM_ECC_WIDTH-1:0]    dccm_data_ecc_hi_m,       
   output logic [pt.DCCM_ECC_WIDTH-1:0]    dccm_data_ecc_lo_m,
   output logic [pt.DCCM_DATA_WIDTH-1:0]   lsu_ld_data_m,            
