module pv_reg (
        input wire clk,
        input wire rst,
        input wire s_cpuif_req,
        input wire s_cpuif_req_is_wr,
        input wire [11:0] s_cpuif_addr,
        input wire [31:0] s_cpuif_wr_data,
        output wire s_cpuif_req_stall_wr,
        output wire s_cpuif_req_stall_rd,
        output wire s_cpuif_rd_ack,
        output wire s_cpuif_rd_err,
        output wire [31:0] s_cpuif_rd_data,
        output wire s_cpuif_wr_ack,
        output wire s_cpuif_wr_err,
        input pv_reg_pkg::pv_reg__in_t hwif_in,
        output pv_reg_pkg::pv_reg__out_t hwif_out
    );
    logic cpuif_req;
    logic cpuif_req_is_wr;
    logic [11:0] cpuif_addr;
    logic [31:0] cpuif_wr_data;
    logic cpuif_req_stall_wr;
    logic cpuif_req_stall_rd;
    logic cpuif_rd_ack;
    logic cpuif_rd_err;
    logic [31:0] cpuif_rd_data;
    logic cpuif_wr_ack;
    logic cpuif_wr_err;
    assign cpuif_req = s_cpuif_req;
    assign cpuif_req_is_wr = s_cpuif_req_is_wr;
    assign cpuif_addr = s_cpuif_addr;
    assign cpuif_wr_data = s_cpuif_wr_data;
    assign s_cpuif_req_stall_wr = cpuif_req_stall_wr;
    assign s_cpuif_req_stall_rd = cpuif_req_stall_rd;
    assign s_cpuif_rd_ack = cpuif_rd_ack;
    assign s_cpuif_rd_err = cpuif_rd_err;
    assign s_cpuif_rd_data = cpuif_rd_data;
    assign s_cpuif_wr_ack = cpuif_wr_ack;
    assign s_cpuif_wr_err = cpuif_wr_err;
    logic cpuif_req_masked;
    assign cpuif_req_stall_rd = '0;
    assign cpuif_req_stall_wr = '0;
    assign cpuif_req_masked = cpuif_req;
    typedef struct packed{
        logic [32-1:0]PCR_CTRL;
        logic [32-1:0][12-1:0]PCR_ENTRY;
    } decoded_reg_strb_t;
    decoded_reg_strb_t decoded_reg_strb;
    logic decoded_req;
    logic decoded_req_is_wr;
    logic [31:0] decoded_wr_data;
    always_comb begin
        for(int i0=0; i0<32; i0++) begin
            decoded_reg_strb.PCR_CTRL[i0] = cpuif_req_masked & (cpuif_addr == 'h0 + i0*'h4);
        end
        for(int i0=0; i0<32; i0++) begin
            for(int i1=0; i1<12; i1++) begin
                decoded_reg_strb.PCR_ENTRY[i0][i1] = cpuif_req_masked & (cpuif_addr == 'h600 + i0*'h30 + i1*'h4);
            end
        end
    end
    assign decoded_req = cpuif_req_masked;
    assign decoded_req_is_wr = cpuif_req_is_wr;
    assign decoded_wr_data = cpuif_wr_data;
    assign cpuif_wr_ack = decoded_req & decoded_req_is_wr;
    assign cpuif_wr_err = '0;
    typedef struct packed{
        struct packed{
            struct packed{
                logic next;
                logic load_next;
            } lock;
            struct packed{
                logic next;
                logic load_next;
            } clear;
            struct packed{
                logic next;
                logic load_next;
            } rsvd0;
            struct packed{
                logic [4:0] next;
                logic load_next;
            } rsvd1;
        } [32-1:0]PCR_CTRL;
        struct packed{
            struct packed{
                logic [31:0] next;
                logic load_next;
            } data;
        } [32-1:0][12-1:0]PCR_ENTRY;
    } field_combo_t;
    field_combo_t field_combo;
    typedef struct packed{
        struct packed{
            struct packed{
                logic value;
            } lock;
            struct packed{
                logic value;
            } clear;
            struct packed{
                logic value;
            } rsvd0;
            struct packed{
                logic [4:0] value;
            } rsvd1;
        } [32-1:0]PCR_CTRL;
        struct packed{
            struct packed{
                logic [31:0] value;
            } data;
        } [32-1:0][12-1:0]PCR_ENTRY;
    } field_storage_t;
    field_storage_t field_storage;
    for(genvar i0=0; i0<32; i0++) begin
        always_comb begin
            automatic logic [0:0] next_c = field_storage.PCR_CTRL[i0].lock.value;
            automatic logic load_next_c = '0;
            if(decoded_reg_strb.PCR_CTRL[i0] && decoded_req_is_wr && !(hwif_in.PCR_CTRL[i0].lock.swwel)) begin  
                next_c = decoded_wr_data[0:0];
                load_next_c = '1;
            end
            field_combo.PCR_CTRL[i0].lock.next = next_c;
            field_combo.PCR_CTRL[i0].lock.load_next = load_next_c;
        end
        always_ff @(posedge clk or negedge hwif_in.hard_reset_b) begin
            if(~hwif_in.hard_reset_b) begin
                field_storage.PCR_CTRL[i0].lock.value <= 'h0;
            end else if(field_combo.PCR_CTRL[i0].lock.load_next) begin
                field_storage.PCR_CTRL[i0].lock.value <= field_combo.PCR_CTRL[i0].lock.next;
            end
        end
        assign hwif_out.PCR_CTRL[i0].lock.value = field_storage.PCR_CTRL[i0].lock.value;
        always_comb begin
            automatic logic [0:0] next_c = field_storage.PCR_CTRL[i0].clear.value;
            automatic logic load_next_c = '0;
            if(decoded_reg_strb.PCR_CTRL[i0] && decoded_req_is_wr && !(hwif_in.PCR_CTRL[i0].clear.swwel)) begin  
                next_c = decoded_wr_data[1:1];
                load_next_c = '1;
            end else if(1) begin  
                next_c = '0;
                load_next_c = '1;
            end
            field_combo.PCR_CTRL[i0].clear.next = next_c;
            field_combo.PCR_CTRL[i0].clear.load_next = load_next_c;
        end
        always_ff @(posedge clk or negedge hwif_in.reset_b) begin
            if(~hwif_in.reset_b) begin
                field_storage.PCR_CTRL[i0].clear.value <= 'h0;
            end else if(field_combo.PCR_CTRL[i0].clear.load_next) begin
                field_storage.PCR_CTRL[i0].clear.value <= field_combo.PCR_CTRL[i0].clear.next;
            end
        end
        assign hwif_out.PCR_CTRL[i0].clear.value = field_storage.PCR_CTRL[i0].clear.value;
        always_comb begin
            automatic logic [0:0] next_c = field_storage.PCR_CTRL[i0].rsvd0.value;
            automatic logic load_next_c = '0;
            if(decoded_reg_strb.PCR_CTRL[i0] && decoded_req_is_wr) begin  
                next_c = decoded_wr_data[2:2];
                load_next_c = '1;
            end else if(hwif_in.PCR_CTRL[i0].rsvd0.hwclr) begin  
                next_c = '0;
                load_next_c = '1;
            end
            field_combo.PCR_CTRL[i0].rsvd0.next = next_c;
            field_combo.PCR_CTRL[i0].rsvd0.load_next = load_next_c;
        end
        always_ff @(posedge clk or negedge hwif_in.reset_b) begin
            if(~hwif_in.reset_b) begin
                field_storage.PCR_CTRL[i0].rsvd0.value <= 'h0;
            end else if(field_combo.PCR_CTRL[i0].rsvd0.load_next) begin
                field_storage.PCR_CTRL[i0].rsvd0.value <= field_combo.PCR_CTRL[i0].rsvd0.next;
            end
        end
        assign hwif_out.PCR_CTRL[i0].rsvd0.value = field_storage.PCR_CTRL[i0].rsvd0.value;
        always_comb begin
            automatic logic [4:0] next_c = field_storage.PCR_CTRL[i0].rsvd1.value;
            automatic logic load_next_c = '0;
            if(decoded_reg_strb.PCR_CTRL[i0] && decoded_req_is_wr) begin  
                next_c = decoded_wr_data[7:3];
                load_next_c = '1;
            end
            field_combo.PCR_CTRL[i0].rsvd1.next = next_c;
            field_combo.PCR_CTRL[i0].rsvd1.load_next = load_next_c;
        end
        always_ff @(posedge clk or negedge hwif_in.reset_b) begin
            if(~hwif_in.reset_b) begin
                field_storage.PCR_CTRL[i0].rsvd1.value <= 'h0;
            end else if(field_combo.PCR_CTRL[i0].rsvd1.load_next) begin
                field_storage.PCR_CTRL[i0].rsvd1.value <= field_combo.PCR_CTRL[i0].rsvd1.next;
            end
        end
        assign hwif_out.PCR_CTRL[i0].rsvd1.value = field_storage.PCR_CTRL[i0].rsvd1.value;
    end
    for(genvar i0=0; i0<32; i0++) begin
        for(genvar i1=0; i1<12; i1++) begin
            always_comb begin
                automatic logic [31:0] next_c = field_storage.PCR_ENTRY[i0][i1].data.value;
                automatic logic load_next_c = '0;
                if(hwif_in.PCR_ENTRY[i0][i1].data.we) begin  
                    next_c = hwif_in.PCR_ENTRY[i0][i1].data.next;
                    load_next_c = '1;
                end else if(hwif_in.PCR_ENTRY[i0][i1].data.hwclr) begin  
                    next_c = '0;
                    load_next_c = '1;
                end
                field_combo.PCR_ENTRY[i0][i1].data.next = next_c;
                field_combo.PCR_ENTRY[i0][i1].data.load_next = load_next_c;
            end
            always_ff @(posedge clk or negedge hwif_in.hard_reset_b) begin
                if(~hwif_in.hard_reset_b) begin
                    field_storage.PCR_ENTRY[i0][i1].data.value <= 'h0;
                end else if(field_combo.PCR_ENTRY[i0][i1].data.load_next) begin
                    field_storage.PCR_ENTRY[i0][i1].data.value <= field_combo.PCR_ENTRY[i0][i1].data.next;
                end
            end
            assign hwif_out.PCR_ENTRY[i0][i1].data.value = field_storage.PCR_ENTRY[i0][i1].data.value;
        end
    end
    logic readback_err;
    logic readback_done;
    logic [31:0] readback_data;
    logic [416-1:0][31:0] readback_array;
    for(genvar i0=0; i0<32; i0++) begin
        assign readback_array[i0*1 + 0][0:0] = (decoded_reg_strb.PCR_CTRL[i0] && !decoded_req_is_wr) ? field_storage.PCR_CTRL[i0].lock.value : '0;
        assign readback_array[i0*1 + 0][1:1] = (decoded_reg_strb.PCR_CTRL[i0] && !decoded_req_is_wr) ? field_storage.PCR_CTRL[i0].clear.value : '0;
        assign readback_array[i0*1 + 0][2:2] = (decoded_reg_strb.PCR_CTRL[i0] && !decoded_req_is_wr) ? field_storage.PCR_CTRL[i0].rsvd0.value : '0;
        assign readback_array[i0*1 + 0][7:3] = (decoded_reg_strb.PCR_CTRL[i0] && !decoded_req_is_wr) ? field_storage.PCR_CTRL[i0].rsvd1.value : '0;
        assign readback_array[i0*1 + 0][31:8] = '0;
    end
    for(genvar i0=0; i0<32; i0++) begin
        for(genvar i1=0; i1<12; i1++) begin
            assign readback_array[i0*12 + i1*1 + 32][31:0] = (decoded_reg_strb.PCR_ENTRY[i0][i1] && !decoded_req_is_wr) ? field_storage.PCR_ENTRY[i0][i1].data.value : '0;
        end
    end
    always_comb begin
        automatic logic [31:0] readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr;
        readback_err = '0;
        readback_data_var = '0;
        for(int i=0; i<416; i++) readback_data_var |= readback_array[i];
        readback_data = readback_data_var;
    end
    assign cpuif_rd_ack = readback_done;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
module pv 
    import pv_defines_pkg::*;
    import pv_reg_pkg::*;
    #(
     parameter AHB_ADDR_WIDTH = PV_ADDR_W
    ,parameter AHB_DATA_WIDTH = 32
    )
    (
    input logic clk,
    input logic rst_b,
    input logic cptra_pwrgood,
    input logic [AHB_ADDR_WIDTH-1:0]      haddr_i,
    input logic [AHB_DATA_WIDTH-1:0]      hwdata_i,
    input logic                           hsel_i,
    input logic                           hwrite_i,
    input logic                           hready_i,
    input logic [1:0]                     htrans_i,
    input logic [2:0]                     hsize_i,
    output logic                          hresp_o,
    output logic                          hreadyout_o,
    output logic [AHB_DATA_WIDTH-1:0]     hrdata_o,
    input pv_read_t [PV_NUM_READ-1:0]     pv_read,
    input pv_write_t [PV_NUM_WRITE-1:0]   pv_write,
    output pv_rd_resp_t [PV_NUM_READ-1:0] pv_rd_resp,
    output pv_wr_resp_t [PV_NUM_READ-1:0] pv_wr_resp
);
logic uc_req_dv, uc_req_hold;
logic uc_req_error;
logic [31:0] uc_req_rdata;
logic pv_reg_read_error, pv_reg_write_error;
logic [AHB_ADDR_WIDTH-1:0] uc_req_addr;
pv_uc_req_t uc_req;
pv_reg__in_t pv_reg_hwif_in;
pv_reg__out_t pv_reg_hwif_out;
ahb_slv_sif #(
    .AHB_ADDR_WIDTH(AHB_ADDR_WIDTH),
    .AHB_DATA_WIDTH(AHB_DATA_WIDTH),
    .CLIENT_DATA_WIDTH(32)
)
pv_ahb_slv1 (
    .hclk(clk),
    .hreset_n(rst_b),
    .haddr_i(haddr_i),
    .hwdata_i(hwdata_i),
    .hsel_i(hsel_i),
    .hwrite_i(hwrite_i),
    .hready_i(hready_i),
    .htrans_i(htrans_i),
    .hsize_i(hsize_i),
    .hresp_o(hresp_o),
    .hreadyout_o(hreadyout_o),
    .hrdata_o(hrdata_o),
    .dv(uc_req_dv),
    .hld(uc_req_hold),
    .err(uc_req_error),
    .write(uc_req.write),
    .wdata(uc_req.wdata),
    .addr(uc_req_addr),
    .rdata(uc_req_rdata)
);
always_comb uc_req.addr = uc_req_addr[PV_ADDR_W-1:0];
always_comb uc_req_error = pv_reg_read_error | pv_reg_write_error;
always_comb uc_req_hold = '0;
always_comb begin : keyvault_ctrl
    for (int entry = 0; entry < PV_NUM_PCR; entry++) begin
        pv_reg_hwif_in.PCR_CTRL[entry].lock.swwel = pv_reg_hwif_out.PCR_CTRL[entry].lock.value;
        pv_reg_hwif_in.PCR_CTRL[entry].clear.swwel = pv_reg_hwif_out.PCR_CTRL[entry].lock.value;
    end
    for (int entry = 0; entry < PV_NUM_PCR; entry++) begin
        for (int dword = 0; dword < PV_NUM_DWORDS; dword++) begin
            pv_reg_hwif_in.PCR_ENTRY[entry][dword].data.next = '0;  
            pv_reg_hwif_in.PCR_ENTRY[entry][dword].data.we = '0;  
            for (int client = 0; client < PV_NUM_WRITE; client++) begin
                pv_reg_hwif_in.PCR_ENTRY[entry][dword].data.hwclr = pv_reg_hwif_out.PCR_CTRL[entry].clear.value;
                pv_reg_hwif_in.PCR_ENTRY[entry][dword].data.we |= pv_write[client].write_en &(pv_write[client].write_entry == entry) & 
                                                                  (pv_write[client].write_offset == dword);
                pv_reg_hwif_in.PCR_ENTRY[entry][dword].data.next |= pv_write[client].write_en & (pv_write[client].write_entry == entry) ? pv_write[client].write_data : '0;
            end 
        end
    end
end
always_comb begin : keyvault_readmux
    for (int client = 0; client < PV_NUM_READ; client++) begin  
        pv_rd_resp[client].read_data = '0;
        pv_rd_resp[client].last = '0;
        pv_rd_resp[client].error = '0;
        for (int entry = 0; entry < PV_NUM_PCR; entry++) begin
            for (int dword = 0; dword < PV_NUM_DWORDS; dword++) begin
                pv_rd_resp[client].read_data |= (pv_read[client].read_entry == entry) & (pv_read[client].read_offset == dword) ? 
                                                 pv_reg_hwif_out.PCR_ENTRY[entry][dword].data.value : '0;
            end
        pv_rd_resp[client].last |= (pv_read[client].read_entry == entry) & (pv_read[client].read_offset == PV_NUM_DWORDS-1);
        pv_rd_resp[client].error |= '0;  
        end
    end
end
always_comb begin : keyvault_write_resp
    for (int client = 0 ; client < PV_NUM_WRITE; client++) begin
        pv_wr_resp[client].error = '0;
        for (int entry = 0; entry < PV_NUM_PCR; entry++) begin
            pv_wr_resp[client].error |= '0;  
        end
    end
end
always_comb begin
    for (int entry = 0; entry < PV_NUM_PCR; entry++) begin
        pv_reg_hwif_in.PCR_CTRL[entry].rsvd0.hwclr = '0;
    end
end
always_comb pv_reg_hwif_in.hard_reset_b = cptra_pwrgood;
always_comb pv_reg_hwif_in.reset_b = rst_b;
pv_reg pv_reg1 (
    .clk(clk),
    .rst('0),
    .s_cpuif_req(uc_req_dv & (uc_req.addr[PV_ADDR_W-1:PV_REG_ADDR_WIDTH] == '0)),
    .s_cpuif_req_is_wr(uc_req.write),
    .s_cpuif_addr(uc_req.addr[PV_REG_ADDR_WIDTH-1:0]),
    .s_cpuif_wr_data(uc_req.wdata),
    .s_cpuif_req_stall_wr(),
    .s_cpuif_req_stall_rd(),
    .s_cpuif_rd_ack(),
    .s_cpuif_rd_err(pv_reg_read_error),
    .s_cpuif_rd_data(uc_req_rdata),
    .s_cpuif_wr_ack(),
    .s_cpuif_wr_err(pv_reg_write_error),
    .hwif_in(pv_reg_hwif_in),
    .hwif_out(pv_reg_hwif_out)
);
endmodule
