        .hld(1'b0),  
        .err(1'b0),
        .write(sha256_we),
        .wdata(sha256_write_data),
        .addr(sha256_address),
        .rdata(sha256_read_data)
    );
endmodule  
module sha256 
            import sha256_reg_pkg::*;
            #(
              parameter ADDR_WIDTH = 32,
              parameter DATA_WIDTH = 32
            )(
              input wire           clk,
              input wire           reset_n,
              input wire           cptra_pwrgood,
              input wire           cs,
              input wire           we,
              input wire  [ADDR_WIDTH-1 : 0] address,
              input wire  [DATA_WIDTH-1 : 0] write_data,
              output wire [DATA_WIDTH-1 : 0] read_data,
              output wire          err,
              output wire error_intr,
              output wire notif_intr
             );
  localparam SHA256_ADDR_NAME0       = 32'h00000000;
  localparam SHA256_ADDR_NAME1       = 32'h00000004;
  localparam SHA256_ADDR_VERSION0    = 32'h00000008;
  localparam SHA256_ADDR_VERSION1    = 32'h0000000c;
  localparam SHA256_ADDR_CTRL        = 32'h00000010;
  localparam SHA256_CTRL_INIT_BIT    = 0;
  localparam SHA256_CTRL_NEXT_BIT    = 1;
  localparam SHA256_CTRL_MODE_BIT    = 2;
  localparam SHA256_ADDR_STATUS      = 32'h00000018;
  localparam SHA256_ADDR_BLOCK_START     = 32'h00000080;
  localparam SHA256_ADDR_BLOCK_END       = 32'h000000bf;
  localparam SHA256_ADDR_DIGEST_START    = 32'h00000100;
  localparam SHA256_ADDR_DIGEST_END      = 32'h0000011f;
  localparam SHA256_ADDR_INTR_START    = 32'h00000800;
  localparam SHA256_ADDR_INTR_END      = 32'h00000BFC;
  localparam SHA256_CORE_NAME0        = 32'h61327368;  
  localparam SHA256_CORE_NAME1        = 32'h35362d32;  
  localparam SHA256_CORE_VERSION0     = 32'h3830312e;  
  localparam SHA256_CORE_VERSION1     = 32'h00000000;  
  localparam SHA256_MODE_SHA_224     = 1'h0;
  localparam SHA256_MODE_SHA_256     = 1'h1;
  reg init_reg;
  reg next_reg;
  reg mode_reg;
  reg ready_reg;
  reg zeroize_reg;
  localparam BLOCK_NO = 512 / DATA_WIDTH;
  reg [DATA_WIDTH-1 : 0] block_reg [BLOCK_NO-1 : 0];
  reg [7 : 0][31 : 0] digest_reg;
  reg                 digest_valid_reg;
  sha256_reg__in_t hwif_in;
  sha256_reg__out_t hwif_out;
  logic read_error, write_error;
  wire              core_ready;
  wire [511 : 0]    core_block;
  wire [7:0][31:0]  core_digest;
  wire              core_digest_valid;
  assign core_block = {block_reg[00], block_reg[01], block_reg[02], block_reg[03],
                       block_reg[04], block_reg[05], block_reg[06], block_reg[07],
                       block_reg[08], block_reg[09], block_reg[10], block_reg[11],
                       block_reg[12], block_reg[13], block_reg[14], block_reg[15]};
  assign err = read_error | write_error;
  sha256_core core(
                   .clk(clk),
                   .reset_n(reset_n),
                   .zeroize(zeroize_reg),
                   .init_cmd(init_reg),
                   .next_cmd(next_reg),
                   .mode(mode_reg),
                   .block_msg(core_block),
                   .ready(core_ready),
                   .digest(core_digest),
                   .digest_valid(core_digest_valid)
                  );
  always @ (posedge clk or negedge reset_n)
    begin : reg_update
      if (!reset_n) begin
        ready_reg        <= '0;
        digest_reg       <= '0;
        digest_valid_reg <= '0;
      end
      else if (zeroize_reg) begin
        ready_reg        <= '0;
        digest_reg       <= '0;
        digest_valid_reg <= '0;
      end
      else begin
        ready_reg        <= core_ready;
        digest_valid_reg <= core_digest_valid;
        if (core_digest_valid & ~digest_valid_reg)
          digest_reg <= core_digest;
      end
    end  
  always_comb begin
    hwif_in.SHA256_NAME[0].NAME.next = SHA256_CORE_NAME0;
    hwif_in.SHA256_NAME[1].NAME.next = SHA256_CORE_NAME1;
    hwif_in.SHA256_VERSION[0].VERSION.next = SHA256_CORE_VERSION0;
    hwif_in.SHA256_VERSION[1].VERSION.next = SHA256_CORE_VERSION1;
    init_reg = hwif_out.SHA256_CTRL.INIT.value;
    next_reg = hwif_out.SHA256_CTRL.NEXT.value;
    mode_reg = hwif_out.SHA256_CTRL.MODE.value;
    zeroize_reg = hwif_out.SHA256_CTRL.ZEROIZE.value;
    hwif_in.SHA256_STATUS.READY.next = ready_reg;
    hwif_in.SHA256_STATUS.VALID.next = digest_valid_reg;
    for (int dword =0; dword < 8; dword++) begin
      hwif_in.SHA256_DIGEST[dword].DIGEST.next = digest_reg[7-dword];
      hwif_in.SHA256_DIGEST[dword].DIGEST.hwclr = zeroize_reg;
    end
    for (int dword=0; dword< BLOCK_NO; dword++) begin
      block_reg[dword] = hwif_out.SHA256_BLOCK[dword].BLOCK.value;
      hwif_in.SHA256_BLOCK[dword].BLOCK.hwclr = zeroize_reg;
    end
  end
  sha256_reg i_sha256_reg (
      .clk(clk),
      .rst(1'b0),
      .s_cpuif_req         (cs),
      .s_cpuif_req_is_wr   (we),
      .s_cpuif_addr        (address[SHA256_REG_ADDR_WIDTH-1:0]),
      .s_cpuif_wr_data     (write_data),
      .s_cpuif_req_stall_wr( ),
      .s_cpuif_req_stall_rd( ),
      .s_cpuif_rd_ack      ( ),
      .s_cpuif_rd_err      (read_error),
      .s_cpuif_rd_data     (read_data),
      .s_cpuif_wr_ack      ( ),
      .s_cpuif_wr_err      (write_error),
      .hwif_in (hwif_in ),
      .hwif_out(hwif_out)
  );
    assign hwif_in.reset_b = reset_n;
    assign hwif_in.error_reset_b = cptra_pwrgood;
    assign hwif_in.intr_block_rf.notif_internal_intr_r.notif_cmd_done_sts.hwset = core_digest_valid & ~digest_valid_reg;
    assign hwif_in.intr_block_rf.error_internal_intr_r.error0_sts.hwset = 1'b0;  
    assign hwif_in.intr_block_rf.error_internal_intr_r.error1_sts.hwset = 1'b0;  
    assign hwif_in.intr_block_rf.error_internal_intr_r.error2_sts.hwset = 1'b0;  
    assign hwif_in.intr_block_rf.error_internal_intr_r.error3_sts.hwset = 1'b0;  
    assign error_intr = hwif_out.intr_block_rf.error_global_intr_r.intr;
    assign notif_intr = hwif_out.intr_block_rf.notif_global_intr_r.intr;    
endmodule  
  localparam SHA256_ADDR_NAME0       = 32'h00000000;
  localparam SHA256_ADDR_NAME1       = 32'h00000004;
  localparam SHA256_ADDR_VERSION0    = 32'h00000008;
  localparam SHA256_ADDR_VERSION1    = 32'h0000000c;
  localparam SHA256_ADDR_CTRL        = 32'h00000010;
  localparam SHA256_CTRL_INIT_BIT    = 0;
  localparam SHA256_CTRL_NEXT_BIT    = 1;
  localparam SHA256_CTRL_MODE_BIT    = 2;
  localparam SHA256_ADDR_STATUS      = 32'h00000018;
  localparam SHA256_ADDR_BLOCK_START     = 32'h00000080;
  localparam SHA256_ADDR_BLOCK_END       = 32'h000000bf;
  localparam SHA256_ADDR_DIGEST_START    = 32'h00000100;
  localparam SHA256_ADDR_DIGEST_END      = 32'h0000011f;
  localparam SHA256_ADDR_INTR_START    = 32'h00000800;
  localparam SHA256_ADDR_INTR_END      = 32'h00000BFC;
  localparam SHA256_CORE_NAME0        = 32'h61327368;  
  localparam SHA256_CORE_NAME1        = 32'h35362d32;  
  localparam SHA256_CORE_VERSION0     = 32'h3830312e;  
  localparam SHA256_CORE_VERSION1     = 32'h00000000;  
  localparam SHA256_MODE_SHA_224     = 1'h0;
  localparam SHA256_MODE_SHA_256     = 1'h1;
module sha256_core(
                   input wire            clk,
                   input wire            reset_n,
                   input wire            zeroize,
                   input wire            init_cmd,
                   input wire            next_cmd,
                   input wire            mode,
                   input wire [511 : 0]  block_msg,
                   output wire           ready,
                   output wire [255 : 0] digest,
                   output wire           digest_valid
                  );
  localparam SHA224_H0_0 = 32'hc1059ed8;
  localparam SHA224_H0_1 = 32'h367cd507;
  localparam SHA224_H0_2 = 32'h3070dd17;
  localparam SHA224_H0_3 = 32'hf70e5939;
  localparam SHA224_H0_4 = 32'hffc00b31;
  localparam SHA224_H0_5 = 32'h68581511;
  localparam SHA224_H0_6 = 32'h64f98fa7;
  localparam SHA224_H0_7 = 32'hbefa4fa4;
  localparam SHA256_H0_0 = 32'h6a09e667;
  localparam SHA256_H0_1 = 32'hbb67ae85;
  localparam SHA256_H0_2 = 32'h3c6ef372;
  localparam SHA256_H0_3 = 32'ha54ff53a;
  localparam SHA256_H0_4 = 32'h510e527f;
  localparam SHA256_H0_5 = 32'h9b05688c;
  localparam SHA256_H0_6 = 32'h1f83d9ab;
  localparam SHA256_H0_7 = 32'h5be0cd19;
  localparam SHA256_ROUNDS = 63;
  localparam [1:0] CTRL_IDLE   = 0;
  localparam [1:0] CTRL_ROUNDS = 1;
  localparam [1:0] CTRL_DONE   = 2;
  reg [31 : 0] a_reg;
  reg [31 : 0] a_new;
  reg [31 : 0] b_reg;
  reg [31 : 0] b_new;
  reg [31 : 0] c_reg;
  reg [31 : 0] c_new;
  reg [31 : 0] d_reg;
  reg [31 : 0] d_new;
  reg [31 : 0] e_reg;
  reg [31 : 0] e_new;
  reg [31 : 0] f_reg;
  reg [31 : 0] f_new;
  reg [31 : 0] g_reg;
  reg [31 : 0] g_new;
  reg [31 : 0] h_reg;
  reg [31 : 0] h_new;
  reg          a_h_we;
  reg [31 : 0] H0_reg;
  reg [31 : 0] H0_new;
  reg [31 : 0] H1_reg;
  reg [31 : 0] H1_new;
  reg [31 : 0] H2_reg;
  reg [31 : 0] H2_new;
  reg [31 : 0] H3_reg;
  reg [31 : 0] H3_new;
  reg [31 : 0] H4_reg;
  reg [31 : 0] H4_new;
  reg [31 : 0] H5_reg;
  reg [31 : 0] H5_new;
  reg [31 : 0] H6_reg;
  reg [31 : 0] H6_new;
  reg [31 : 0] H7_reg;
  reg [31 : 0] H7_new;
  reg          H_we;
  reg [5 : 0] t_ctr_reg;
  reg [5 : 0] t_ctr_new;
  reg         t_ctr_we;
  reg         t_ctr_inc;
  reg         t_ctr_rst;
  reg digest_valid_reg;
  reg digest_valid_new;
  reg digest_valid_we;
  reg [1 : 0] sha256_ctrl_reg;
  reg [1 : 0] sha256_ctrl_new;
  reg         sha256_ctrl_we;
  reg digest_init;
  reg digest_update;
  reg state_init;
  reg state_update;
  reg first_block;
  reg ready_flag;
  reg [31 : 0] t1;
  reg [31 : 0] t2;
  wire [31 : 0] k_data;
  reg           w_init;
  reg           w_next;
  wire [31 : 0] w_data;
  sha256_k_constants k_constants_inst(
                                      .round(t_ctr_reg),
                                      .K_val(k_data)
                                     );
  sha256_w_mem w_mem_inst(
                          .clk(clk),
                          .reset_n(reset_n),
                          .zeroize(zeroize),
                          .block_msg(block_msg),
                          .init_cmd(w_init),
                          .next_cmd(w_next),
                          .w_val(w_data)
                         );
  assign ready = ready_flag;
  assign digest = {H0_reg, H1_reg, H2_reg, H3_reg,
                   H4_reg, H5_reg, H6_reg, H7_reg};
  assign digest_valid = digest_valid_reg;
  always @ (posedge clk or negedge reset_n)
    begin : reg_update
      if (!reset_n)
        begin
          a_reg            <= 32'h0;
          b_reg            <= 32'h0;
          c_reg            <= 32'h0;
          d_reg            <= 32'h0;
          e_reg            <= 32'h0;
          f_reg            <= 32'h0;
          g_reg            <= 32'h0;
          h_reg            <= 32'h0;
          H0_reg           <= 32'h0;
          H1_reg           <= 32'h0;
          H2_reg           <= 32'h0;
          H3_reg           <= 32'h0;
          H4_reg           <= 32'h0;
          H5_reg           <= 32'h0;
          H6_reg           <= 32'h0;
          H7_reg           <= 32'h0;
          digest_valid_reg <= 0;
          t_ctr_reg        <= 6'h0;
          sha256_ctrl_reg  <= CTRL_IDLE;
        end
      else if (zeroize)
        begin
          a_reg            <= 32'h0;
          b_reg            <= 32'h0;
          c_reg            <= 32'h0;
          d_reg            <= 32'h0;
          e_reg            <= 32'h0;
          f_reg            <= 32'h0;
          g_reg            <= 32'h0;
          h_reg            <= 32'h0;
          H0_reg           <= 32'h0;
          H1_reg           <= 32'h0;
          H2_reg           <= 32'h0;
          H3_reg           <= 32'h0;
          H4_reg           <= 32'h0;
          H5_reg           <= 32'h0;
          H6_reg           <= 32'h0;
          H7_reg           <= 32'h0;
          digest_valid_reg <= 0;
          t_ctr_reg        <= 6'h0;
          sha256_ctrl_reg  <= CTRL_IDLE;
        end
      else
        begin
          if (a_h_we)
            begin
              a_reg <= a_new;
              b_reg <= b_new;
              c_reg <= c_new;
              d_reg <= d_new;
              e_reg <= e_new;
              f_reg <= f_new;
              g_reg <= g_new;
              h_reg <= h_new;
            end
          if (H_we)
            begin
              H0_reg <= H0_new;
              H1_reg <= H1_new;
              H2_reg <= H2_new;
              H3_reg <= H3_new;
              H4_reg <= H4_new;
              H5_reg <= H5_new;
              H6_reg <= H6_new;
              H7_reg <= H7_new;
            end
          if (t_ctr_we)
            t_ctr_reg <= t_ctr_new;
          if (digest_valid_we)
            digest_valid_reg <= digest_valid_new;
          if (sha256_ctrl_we)
            sha256_ctrl_reg <= sha256_ctrl_new;
        end
    end  
  always @*
    begin : digest_logic
      H0_new = 32'h0;
      H1_new = 32'h0;
      H2_new = 32'h0;
      H3_new = 32'h0;
      H4_new = 32'h0;
      H5_new = 32'h0;
      H6_new = 32'h0;
      H7_new = 32'h0;
      H_we = 0;
      if (digest_init)
        begin
          H_we = 1;
          if (mode)
            begin
              H0_new = SHA256_H0_0;
              H1_new = SHA256_H0_1;
              H2_new = SHA256_H0_2;
              H3_new = SHA256_H0_3;
              H4_new = SHA256_H0_4;
              H5_new = SHA256_H0_5;
              H6_new = SHA256_H0_6;
              H7_new = SHA256_H0_7;
            end
          else
            begin
              H0_new = SHA224_H0_0;
              H1_new = SHA224_H0_1;
              H2_new = SHA224_H0_2;
              H3_new = SHA224_H0_3;
              H4_new = SHA224_H0_4;
              H5_new = SHA224_H0_5;
              H6_new = SHA224_H0_6;
              H7_new = SHA224_H0_7;
            end
        end
      if (digest_update)
        begin
          H0_new = H0_reg + a_reg;
          H1_new = H1_reg + b_reg;
          H2_new = H2_reg + c_reg;
          H3_new = H3_reg + d_reg;
          H4_new = H4_reg + e_reg;
          H5_new = H5_reg + f_reg;
          H6_new = H6_reg + g_reg;
          H7_new = H7_reg + h_reg;
          H_we = 1;
        end
    end  
  always @*
    begin : t1_logic
      reg [31 : 0] sum1;
      reg [31 : 0] ch;
      sum1 = {e_reg[5  : 0], e_reg[31 :  6]} ^
             {e_reg[10 : 0], e_reg[31 : 11]} ^
             {e_reg[24 : 0], e_reg[31 : 25]};
      ch = (e_reg & f_reg) ^ ((~e_reg) & g_reg);
      t1 = h_reg + sum1 + ch + w_data + k_data;
    end  
  always @*
    begin : t2_logic
      reg [31 : 0] sum0;
      reg [31 : 0] maj;
      sum0 = {a_reg[1  : 0], a_reg[31 :  2]} ^
             {a_reg[12 : 0], a_reg[31 : 13]} ^
             {a_reg[21 : 0], a_reg[31 : 22]};
      maj = (a_reg & b_reg) ^ (a_reg & c_reg) ^ (b_reg & c_reg);
      t2 = sum0 + maj;
    end  
  always @*
    begin : state_logic
      a_new  = 32'h0;
      b_new  = 32'h0;
      c_new  = 32'h0;
      d_new  = 32'h0;
      e_new  = 32'h0;
      f_new  = 32'h0;
      g_new  = 32'h0;
      h_new  = 32'h0;
      a_h_we = 0;
      if (state_init)
        begin
          a_h_we = 1;
          if (first_block)
            begin
              if (mode)
                begin
                  a_new  = SHA256_H0_0;
                  b_new  = SHA256_H0_1;
                  c_new  = SHA256_H0_2;
                  d_new  = SHA256_H0_3;
                  e_new  = SHA256_H0_4;
                  f_new  = SHA256_H0_5;
                  g_new  = SHA256_H0_6;
                  h_new  = SHA256_H0_7;
                end
              else
                begin
                  a_new  = SHA224_H0_0;
                  b_new  = SHA224_H0_1;
                  c_new  = SHA224_H0_2;
                  d_new  = SHA224_H0_3;
                  e_new  = SHA224_H0_4;
                  f_new  = SHA224_H0_5;
                  g_new  = SHA224_H0_6;
                  h_new  = SHA224_H0_7;
                end
            end
          else
            begin
              a_new  = H0_reg;
              b_new  = H1_reg;
              c_new  = H2_reg;
              d_new  = H3_reg;
              e_new  = H4_reg;
              f_new  = H5_reg;
              g_new  = H6_reg;
              h_new  = H7_reg;
            end
        end
      if (state_update)
        begin
          a_new  = t1 + t2;
          b_new  = a_reg;
          c_new  = b_reg;
          d_new  = c_reg;
          e_new  = d_reg + t1;
          f_new  = e_reg;
          g_new  = f_reg;
          h_new  = g_reg;
          a_h_we = 1;
        end
    end  
  always @*
    begin : t_ctr
      t_ctr_new = 0;
      t_ctr_we  = 0;
      if (t_ctr_rst)
        begin
          t_ctr_new = 0;
          t_ctr_we  = 1;
        end
      if (t_ctr_inc)
        begin
          t_ctr_new = t_ctr_reg + 1'b1;
          t_ctr_we  = 1;
        end
    end  
  always @*
    begin : sha256_ctrl_fsm
      digest_init      = 0;
      digest_update    = 0;
      state_init       = 0;
      state_update     = 0;
      first_block      = 0;
      ready_flag       = 0;
      w_init           = 0;
      w_next           = 0;
      t_ctr_inc        = 0;
      t_ctr_rst        = 0;
      digest_valid_new = 0;
      digest_valid_we  = 0;
      sha256_ctrl_new  = CTRL_IDLE;
      sha256_ctrl_we   = 0;
      case (sha256_ctrl_reg)
        CTRL_IDLE:
          begin
            ready_flag = 1;
            if (init_cmd)
              begin
                digest_init      = 1;
                w_init           = 1;
                state_init       = 1;
                first_block      = 1;
                t_ctr_rst        = 1;
                digest_valid_new = 0;
                digest_valid_we  = 1;
                sha256_ctrl_new  = CTRL_ROUNDS;
                sha256_ctrl_we   = 1;
              end
            if (next_cmd)
              begin
                t_ctr_rst        = 1;
                w_init           = 1;
                state_init       = 1;
                digest_valid_new = 0;
                digest_valid_we  = 1;
                sha256_ctrl_new  = CTRL_ROUNDS;
                sha256_ctrl_we   = 1;
              end
          end
        CTRL_ROUNDS:
          begin
            w_next       = 1;
            state_update = 1;
            t_ctr_inc    = 1;
            if (t_ctr_reg == SHA256_ROUNDS)
              begin
                sha256_ctrl_new = CTRL_DONE;
                sha256_ctrl_we  = 1;
              end
          end
        CTRL_DONE:
          begin
            digest_update    = 1;
            digest_valid_new = 1;
            digest_valid_we  = 1;
            sha256_ctrl_new  = CTRL_IDLE;
            sha256_ctrl_we   = 1;
          end
        default:
          begin
            sha256_ctrl_new = sha256_ctrl_reg;
            sha256_ctrl_we   = 0;
          end
      endcase  
    end  
endmodule  
module sha256_k_constants(
                          input wire  [5 : 0] round,
                          output wire [31 : 0] K_val
                         );
  reg [31 : 0] tmp_K;
  assign K_val = tmp_K;
  always @*
    begin : round_mux
      case(round)
        00: tmp_K = 32'h428a2f98;
        01: tmp_K = 32'h71374491;
        02: tmp_K = 32'hb5c0fbcf;
        03: tmp_K = 32'he9b5dba5;
        04: tmp_K = 32'h3956c25b;
        05: tmp_K = 32'h59f111f1;
        06: tmp_K = 32'h923f82a4;
        07: tmp_K = 32'hab1c5ed5;
        08: tmp_K = 32'hd807aa98;
        09: tmp_K = 32'h12835b01;
        10: tmp_K = 32'h243185be;
        11: tmp_K = 32'h550c7dc3;
        12: tmp_K = 32'h72be5d74;
        13: tmp_K = 32'h80deb1fe;
        14: tmp_K = 32'h9bdc06a7;
        15: tmp_K = 32'hc19bf174;
        16: tmp_K = 32'he49b69c1;
        17: tmp_K = 32'hefbe4786;
        18: tmp_K = 32'h0fc19dc6;
        19: tmp_K = 32'h240ca1cc;
        20: tmp_K = 32'h2de92c6f;
        21: tmp_K = 32'h4a7484aa;
        22: tmp_K = 32'h5cb0a9dc;
        23: tmp_K = 32'h76f988da;
        24: tmp_K = 32'h983e5152;
        25: tmp_K = 32'ha831c66d;
