module doe_cbc 
  import doe_defines_pkg::*;
  import kv_defines_pkg::*;
  import doe_reg_pkg::*;
 #(
    parameter ADDR_WIDTH = 32,
    parameter DATA_WIDTH = 32
  )
  (
   input wire           clk,
   input wire           reset_n,
   input wire           cptra_pwrgood,
   input wire [8-1:0][31:0] cptra_obf_key,
   input wire [8-1 :0][31:0] obf_field_entropy,
   input wire [12-1:0][31:0] obf_uds_seed,
   input wire           cs,
   input wire           we,
   input wire  [ADDR_WIDTH-1 : 0] address,
   input wire  [DATA_WIDTH-1 : 0] write_data,
   output wire [DATA_WIDTH-1 : 0] read_data,
   output logic error_intr,
   output logic notif_intr,
   output logic clear_obf_secrets,
   output kv_write_t kv_write
  );
  localparam BLOCK_NO = 128 / DATA_WIDTH;
  localparam IV_NO = 128 / DATA_WIDTH;
  logic [BLOCK_NO-1:0][DATA_WIDTH-1:0] block_reg;
  logic [IV_NO-1:0][DATA_WIDTH-1:0] IV_reg;
  reg [127 : 0] kv_result_reg;
  reg           ready_reg;
  wire           core_encdec;
  wire           core_init;
  wire           core_next;
  wire           core_ready;
  wire [255 : 0] core_key;
  wire           core_keylen;
  wire [127 : 0] core_block;
  wire [127 : 0] core_IV;
  wire [127 : 0] core_result;
  wire           core_valid;
  doe_cmd_reg_t doe_cmd_reg;
  logic IV_updated;
  logic doe_block_write_en;
  logic [127:0] doe_block_write_data;
  logic doe_init;
  logic doe_next;
  logic flow_done;
  logic flow_in_progress, lock_fe_flow, lock_uds_flow;
  doe_reg__in_t  hwif_in;
  doe_reg__out_t hwif_out;
  assign core_key     = {cptra_obf_key[0], cptra_obf_key[1], cptra_obf_key[2], cptra_obf_key[3], cptra_obf_key[4], cptra_obf_key[5], cptra_obf_key[6], cptra_obf_key[7]};
  assign core_block   = {block_reg[0], block_reg[1], block_reg[2], block_reg[3]};
  assign core_IV      = {IV_reg[0], IV_reg[1], IV_reg[2], IV_reg[3]};
  assign core_init   = doe_init;
  assign core_next   = doe_next;
  assign core_encdec = '0;  
  assign core_keylen = '1;  
  doe_core_cbc i_doe_core_cbc(
                .clk(clk),
                .reset_n(reset_n),
                .encdec(core_encdec),
                .init_cmd(core_init),
                .next_cmd(core_next),
                .ready(core_ready),
                .key(core_key),
                .keylen(core_keylen),
                .IV(core_IV),
                .IV_updated(IV_updated),
                .block_msg(core_block),
                .result(core_result),
                .result_valid(core_valid)
               );
  always @ (posedge clk or negedge reset_n) begin : reg_update
      if (!reset_n) begin
          block_reg <= '0;
          ready_reg <= '0;
          kv_result_reg <= '0;
      end
      else begin
          ready_reg  <= core_ready;
          kv_result_reg <= core_result;
          block_reg <= doe_block_write_en ? doe_block_write_data : block_reg;
        end
  end 
assign hwif_in.DOE_STATUS.UDS_FLOW_DONE.next = lock_uds_flow;
assign hwif_in.DOE_STATUS.FE_FLOW_DONE.next  = lock_fe_flow;
assign hwif_in.DOE_STATUS.DEOBF_SECRETS_CLEARED.hwset = clear_obf_secrets;
assign hwif_in.DOE_STATUS.READY.hwset = ready_reg & ~(flow_in_progress);
assign hwif_in.DOE_STATUS.READY.hwclr = ~ready_reg;
assign hwif_in.DOE_STATUS.VALID.hwset = flow_done | clear_obf_secrets;
assign hwif_in.DOE_STATUS.VALID.hwclr = hwif_out.DOE_CTRL.CMD.swmod;
assign hwif_in.DOE_CTRL.CMD.hwclr = flow_done | clear_obf_secrets;
assign doe_cmd_reg.cmd = doe_cmd_e'(hwif_out.DOE_CTRL.CMD.value);
assign doe_cmd_reg.dest_sel = hwif_out.DOE_CTRL.DEST.value;
always_comb clear_obf_secrets = (doe_cmd_reg.cmd == DOE_CLEAR);
always_comb begin
  IV_updated = '0;
  for (int dword = 0; dword < IV_NO; dword++) begin
    IV_reg[dword] = hwif_out.DOE_IV[dword].IV.value;
    IV_updated |= hwif_out.DOE_IV[dword].IV.swmod;
  end
end
doe_fsm
doe_fsm1 
(
  .clk(clk),
  .rst_b(reset_n),
  .hard_rst_b(cptra_pwrgood),
  .obf_field_entropy(obf_field_entropy),
  .obf_uds_seed(obf_uds_seed),
  .doe_cmd_reg(doe_cmd_reg),
  .kv_write(kv_write),
  .src_write_en(doe_block_write_en),
  .src_write_data(doe_block_write_data),
  .doe_init(doe_init),
  .doe_next(doe_next),
  .init_done(core_ready),
  .dest_data_avail(core_valid),
  .dest_data(kv_result_reg),
  .flow_done(flow_done),
  .flow_in_progress(flow_in_progress),
  .lock_uds_flow(lock_uds_flow),
  .lock_fe_flow(lock_fe_flow)
);
always_comb hwif_in.reset_b = reset_n;
always_comb hwif_in.cptra_pwrgood = cptra_pwrgood;
always_comb hwif_in.intr_block_rf.error_internal_intr_r.error0_sts.hwset  = 1'b0;  
always_comb hwif_in.intr_block_rf.error_internal_intr_r.error1_sts.hwset  = 1'b0;  
always_comb hwif_in.intr_block_rf.error_internal_intr_r.error2_sts.hwset  = 1'b0;  
always_comb hwif_in.intr_block_rf.error_internal_intr_r.error3_sts.hwset  = 1'b0;  
always_comb hwif_in.intr_block_rf.notif_internal_intr_r.notif_cmd_done_sts.hwset = flow_done;
doe_reg i_doe_reg (
        .clk(clk),
        .rst(reset_n),
        .s_cpuif_req         (cs),
        .s_cpuif_req_is_wr   (we),
        .s_cpuif_addr        (address[DOE_REG_ADDR_WIDTH-1:0]),
        .s_cpuif_wr_data     (write_data[31:0]),
        .s_cpuif_req_stall_wr(),
        .s_cpuif_req_stall_rd(),
        .s_cpuif_rd_ack      (),
        .s_cpuif_rd_err      ( ),
        .s_cpuif_rd_data     (read_data     ),
        .s_cpuif_wr_ack      (),
        .s_cpuif_wr_err      ( ),
        .hwif_in             (hwif_in ),
        .hwif_out            (hwif_out)
    );
assign error_intr = hwif_out.intr_block_rf.error_global_intr_r.intr;
assign notif_intr = hwif_out.intr_block_rf.notif_global_intr_r.intr;
endmodule  
module doe_core_cbc(
                input wire            clk,
                input wire            reset_n,
                input wire            encdec,
                input wire            init_cmd,
                input wire            next_cmd,
                output wire           ready,
                input wire [255 : 0]  key,
                input wire            keylen,
                input wire [127 : 0]  IV,
                input wire            IV_updated,
                input wire [127 : 0]  block_msg,
                output wire [127 : 0] result,
                output wire           result_valid
               );
  localparam CTRL_IDLE  = 2'h0;
  localparam CTRL_INIT  = 2'h1;
  localparam CTRL_NEXT  = 2'h2;
  reg [1 : 0] doe_core_ctrl_reg;
  reg [1 : 0] doe_core_ctrl_new;
  reg         doe_core_ctrl_we;
  reg         result_valid_reg;
  reg         result_valid_new;
  reg         result_valid_we;
  reg         ready_reg;
  reg         ready_new;
  reg         ready_we;
  reg            init_state;
  wire [127 : 0] round_key;
  wire           key_ready;
  reg            enc_next;
  wire [3 : 0]   enc_round_nr;
  wire [127 : 0] enc_new_block;
  wire           enc_ready;
  wire [31 : 0]  enc_sboxw;
  reg            dec_next;
  wire [3 : 0]   dec_round_nr;
  wire [127 : 0] dec_new_block;
  wire           dec_ready;
  reg [127 : 0]  muxed_new_block;
  reg [3 : 0]    muxed_round_nr;
  reg            muxed_ready;
  wire [31 : 0]  keymem_sboxw;
/*verilator lint_off UNOPTFLAT*/ 
  reg [31 : 0]   muxed_sboxw;
  wire [31 : 0]  new_sboxw;
/*verilator lint_on UNOPTFLAT*/ 
  reg [127 : 0]  IV_encry;
  reg [127 : 0]  IV_decry;
  reg [127 : 0]  IV_decry_next;
  reg IV_updated_delayed;
  reg [1:0] IV_enc_state;
  reg [1:0] IV_dec_state;
  reg [127:0] block_msg_encr;
  localparam st_IV_engine_idle  = 2'h0,
             st_IV_engine_stars = 2'h1,
             st_IV_1st_decrypt  = 2'h2;
  assign block_msg_encr = block_msg ^ IV_encry;
  doe_encipher_block enc_block(
                               .clk(clk),
                               .reset_n(reset_n),
                               .next_cmd(enc_next),
                               .keylen(keylen),
                               .round(enc_round_nr),
                               .round_key(round_key),
                               .sboxw(enc_sboxw),
                               .new_sboxw(new_sboxw),
                               .block_msg(block_msg_encr),
                               .new_block(enc_new_block),
                               .ready(enc_ready)
                              );
  doe_decipher_block dec_block(
                               .clk(clk),
                               .reset_n(reset_n),
                               .next_cmd(dec_next),
                               .keylen(keylen),
                               .round(dec_round_nr),
                               .round_key(round_key),
                               .block_msg(block_msg),
                               .new_block(dec_new_block),
                               .ready(dec_ready)
                              );
  doe_key_mem keymem(
                     .clk(clk),
                     .reset_n(reset_n),
                     .key(key),
                     .keylen(keylen),
                     .init_cmd(init_cmd),
                     .round(muxed_round_nr),
                     .round_key(round_key),
                     .ready(key_ready),
                     .sboxw(keymem_sboxw),
                     .new_sboxw(new_sboxw)
                    );
  doe_sbox sbox_inst(.sboxw(muxed_sboxw), .new_sboxw(new_sboxw));
  always @ (posedge clk or negedge reset_n)
  begin:IV_storage_management
      if (!reset_n)
        begin
          IV_encry            <= 128'h0;
          IV_decry            <= 128'h0;
          IV_decry_next       <= 128'h0;
          IV_enc_state        <= st_IV_engine_idle;
          IV_dec_state        <= st_IV_engine_idle;
          IV_updated_delayed  <= 1'b0;
        end
      else
        begin
            if(IV_updated_delayed)
                IV_encry <= IV;
            else if ((IV_enc_state == st_IV_engine_stars) && enc_ready)
                IV_encry <= enc_new_block;
            else
                IV_encry <= IV_encry;
            case (IV_enc_state)
                st_IV_engine_idle:
                begin
                    if(enc_ready & enc_next)
                        IV_enc_state <= st_IV_engine_stars;
                    else
                        IV_enc_state <= st_IV_engine_idle;                 
                end
                st_IV_engine_stars:
                begin
                    if (IV_updated_delayed)
                        IV_enc_state <= st_IV_engine_idle; 
                    else if(enc_ready)
                        IV_enc_state <= st_IV_engine_idle;
                    else
                        IV_enc_state <= st_IV_engine_stars;                 
                end
                default:
                begin
                  IV_enc_state <= st_IV_engine_idle;
                end
            endcase  
            case (IV_dec_state)
                st_IV_engine_idle:
                begin
                    IV_decry_next <= block_msg;
                    IV_decry      <= IV;
                    if(dec_ready & dec_next)
                        IV_dec_state <= st_IV_1st_decrypt;
                    else
                        IV_dec_state  <= st_IV_engine_idle;                 
                end
                st_IV_1st_decrypt:
                begin                    
                    if(IV_updated_delayed)
                    begin
                        IV_decry_next <= IV;
                        IV_decry      <= IV;
                        IV_dec_state  <= st_IV_engine_idle;
                    end
                    else if(dec_ready & dec_next)
                    begin
                        IV_dec_state  <= st_IV_engine_stars;
                        IV_decry_next <= block_msg;
                        IV_decry      <= IV_decry_next;
                    end
                    else
                    begin
                        IV_dec_state  <= st_IV_1st_decrypt;
                        IV_decry_next <= IV_decry_next;
                        IV_decry      <= IV_decry;
                    end              
                end
                st_IV_engine_stars:
                begin
                    IV_dec_state  <= st_IV_1st_decrypt;
                    IV_decry_next <= IV_decry_next;
                    IV_decry      <= IV_decry;             
                end
                default:
                begin 
                    IV_dec_state  <= st_IV_engine_idle; 
                    IV_decry_next <= IV;
                    IV_decry      <= IV;
                end
            endcase  
            IV_updated_delayed <= IV_updated;      
        end
  end  
  assign ready        = ready_reg;
  assign result       = muxed_new_block;
  assign result_valid = result_valid_reg;
  always @ (posedge clk or negedge reset_n)
    begin: reg_update
      if (!reset_n)
        begin
          result_valid_reg  <= 1'b0;
          ready_reg         <= 1'b1;
          doe_core_ctrl_reg <= CTRL_IDLE;
        end
      else
        begin
          if (result_valid_we)
            result_valid_reg <= result_valid_new;
          if (ready_we)
            ready_reg <= ready_new;
          if (doe_core_ctrl_we)
            doe_core_ctrl_reg <= doe_core_ctrl_new;
        end
    end  
  always @*
    begin : sbox_mux
      if (init_state)
        begin
          muxed_sboxw = keymem_sboxw;
        end
      else
        begin
          muxed_sboxw = enc_sboxw;
        end
    end  
  always @*
    begin : encdec_mux
      enc_next = 1'b0;
      dec_next = 1'b0;
      if (encdec)
        begin
          enc_next        = next_cmd;
          muxed_round_nr  = enc_round_nr;
          muxed_new_block = enc_new_block;
          muxed_ready     = enc_ready;
        end
      else
        begin
          dec_next        = next_cmd;
          muxed_round_nr  = dec_round_nr;
          muxed_new_block = dec_new_block^IV_decry;
          muxed_ready     = dec_ready;
        end
    end  
  always @*
    begin : doe_core_ctrl
      init_state        = 1'b0;
      ready_new         = 1'b0;
      ready_we          = 1'b0;
      result_valid_new  = 1'b0;
      result_valid_we   = 1'b0;
      doe_core_ctrl_new = CTRL_IDLE;
      doe_core_ctrl_we  = 1'b0;
      case (doe_core_ctrl_reg)
        CTRL_IDLE:
          begin
            if (init_cmd)
              begin
                init_state        = 1'b1;
                ready_new         = 1'b0;
                ready_we          = 1'b1;
                result_valid_new  = 1'b0;
                result_valid_we   = 1'b1;
                doe_core_ctrl_new = CTRL_INIT;
                doe_core_ctrl_we  = 1'b1;
              end
            else if (next_cmd)
              begin
                init_state        = 1'b0;
                ready_new         = 1'b0;
                ready_we          = 1'b1;
                result_valid_new  = 1'b0;
                result_valid_we   = 1'b1;
                doe_core_ctrl_new = CTRL_NEXT;
                doe_core_ctrl_we  = 1'b1;
              end
          end
        CTRL_INIT:
          begin
            init_state = 1'b1;
            if (key_ready)
              begin
                ready_new         = 1'b1;
                ready_we          = 1'b1;
                doe_core_ctrl_new = CTRL_IDLE;
                doe_core_ctrl_we  = 1'b1;
              end
          end
        CTRL_NEXT:
          begin
            init_state = 1'b0;
            if (muxed_ready)
              begin
                ready_new         = 1'b1;
                ready_we          = 1'b1;
                result_valid_new  = 1'b1;
                result_valid_we   = 1'b1;
                doe_core_ctrl_new = CTRL_IDLE;
                doe_core_ctrl_we  = 1'b1;
             end
          end
        default:
          begin
            init_state        = 1'b0;
            ready_new         = 1'b0;
            ready_we          = 1'b0;
            result_valid_new  = 1'b0;
            result_valid_we   = 1'b0;
            doe_core_ctrl_new = CTRL_IDLE;
            doe_core_ctrl_we  = 1'b0;
          end
      endcase  
    end  
endmodule  
module doe_reg (
        input wire clk,
        input wire rst,
        input wire s_cpuif_req,
        input wire s_cpuif_req_is_wr,
        input wire [11:0] s_cpuif_addr,
        input wire [31:0] s_cpuif_wr_data,
        output wire s_cpuif_req_stall_wr,
        output wire s_cpuif_req_stall_rd,
        output wire s_cpuif_rd_ack,
        output wire s_cpuif_rd_err,
        output wire [31:0] s_cpuif_rd_data,
        output wire s_cpuif_wr_ack,
        output wire s_cpuif_wr_err,
        input doe_reg_pkg::doe_reg__in_t hwif_in,
        output doe_reg_pkg::doe_reg__out_t hwif_out
    );
    logic cpuif_req;
    logic cpuif_req_is_wr;
    logic [11:0] cpuif_addr;
    logic [31:0] cpuif_wr_data;
    logic cpuif_req_stall_wr;
    logic cpuif_req_stall_rd;
    logic cpuif_rd_ack;
    logic cpuif_rd_err;
    logic [31:0] cpuif_rd_data;
    logic cpuif_wr_ack;
    logic cpuif_wr_err;
    assign cpuif_req = s_cpuif_req;
    assign cpuif_req_is_wr = s_cpuif_req_is_wr;
    assign cpuif_addr = s_cpuif_addr;
    assign cpuif_wr_data = s_cpuif_wr_data;
    assign s_cpuif_req_stall_wr = cpuif_req_stall_wr;
    assign s_cpuif_req_stall_rd = cpuif_req_stall_rd;
    assign s_cpuif_rd_ack = cpuif_rd_ack;
    assign s_cpuif_rd_err = cpuif_rd_err;
    assign s_cpuif_rd_data = cpuif_rd_data;
    assign s_cpuif_wr_ack = cpuif_wr_ack;
    assign s_cpuif_wr_err = cpuif_wr_err;
    logic cpuif_req_masked;
    assign cpuif_req_stall_rd = '0;
    assign cpuif_req_stall_wr = '0;
    assign cpuif_req_masked = cpuif_req;
    typedef struct packed{
        logic [4-1:0]DOE_IV;
        logic DOE_CTRL;
        logic DOE_STATUS;
        struct packed{
            logic global_intr_en_r;
            logic error_intr_en_r;
            logic notif_intr_en_r;
            logic error_global_intr_r;
            logic notif_global_intr_r;
            logic error_internal_intr_r;
            logic notif_internal_intr_r;
            logic error_intr_trig_r;
            logic notif_intr_trig_r;
            logic error0_intr_count_r;
            logic error1_intr_count_r;
            logic error2_intr_count_r;
            logic error3_intr_count_r;
            logic notif_cmd_done_intr_count_r;
            logic error0_intr_count_incr_r;
            logic error1_intr_count_incr_r;
            logic error2_intr_count_incr_r;
            logic error3_intr_count_incr_r;
            logic notif_cmd_done_intr_count_incr_r;
        } intr_block_rf;
    } decoded_reg_strb_t;
    decoded_reg_strb_t decoded_reg_strb;
    logic decoded_req;
    logic decoded_req_is_wr;
    logic [31:0] decoded_wr_data;
    always_comb begin
        for(int i0=0; i0<4; i0++) begin
            decoded_reg_strb.DOE_IV[i0] = cpuif_req_masked & (cpuif_addr == 'h0 + i0*'h4);
        end
        decoded_reg_strb.DOE_CTRL = cpuif_req_masked & (cpuif_addr == 'h10);
        decoded_reg_strb.DOE_STATUS = cpuif_req_masked & (cpuif_addr == 'h14);
        decoded_reg_strb.intr_block_rf.global_intr_en_r = cpuif_req_masked & (cpuif_addr == 'h800);
        decoded_reg_strb.intr_block_rf.error_intr_en_r = cpuif_req_masked & (cpuif_addr == 'h804);
        decoded_reg_strb.intr_block_rf.notif_intr_en_r = cpuif_req_masked & (cpuif_addr == 'h808);
        decoded_reg_strb.intr_block_rf.error_global_intr_r = cpuif_req_masked & (cpuif_addr == 'h80c);
        decoded_reg_strb.intr_block_rf.notif_global_intr_r = cpuif_req_masked & (cpuif_addr == 'h810);
        decoded_reg_strb.intr_block_rf.error_internal_intr_r = cpuif_req_masked & (cpuif_addr == 'h814);
        decoded_reg_strb.intr_block_rf.notif_internal_intr_r = cpuif_req_masked & (cpuif_addr == 'h818);
        decoded_reg_strb.intr_block_rf.error_intr_trig_r = cpuif_req_masked & (cpuif_addr == 'h81c);
        decoded_reg_strb.intr_block_rf.notif_intr_trig_r = cpuif_req_masked & (cpuif_addr == 'h820);
        decoded_reg_strb.intr_block_rf.error0_intr_count_r = cpuif_req_masked & (cpuif_addr == 'h900);
        decoded_reg_strb.intr_block_rf.error1_intr_count_r = cpuif_req_masked & (cpuif_addr == 'h904);
        decoded_reg_strb.intr_block_rf.error2_intr_count_r = cpuif_req_masked & (cpuif_addr == 'h908);
        decoded_reg_strb.intr_block_rf.error3_intr_count_r = cpuif_req_masked & (cpuif_addr == 'h90c);
        decoded_reg_strb.intr_block_rf.notif_cmd_done_intr_count_r = cpuif_req_masked & (cpuif_addr == 'h980);
        decoded_reg_strb.intr_block_rf.error0_intr_count_incr_r = cpuif_req_masked & (cpuif_addr == 'ha00);
        decoded_reg_strb.intr_block_rf.error1_intr_count_incr_r = cpuif_req_masked & (cpuif_addr == 'ha04);
        decoded_reg_strb.intr_block_rf.error2_intr_count_incr_r = cpuif_req_masked & (cpuif_addr == 'ha08);
        decoded_reg_strb.intr_block_rf.error3_intr_count_incr_r = cpuif_req_masked & (cpuif_addr == 'ha0c);
        decoded_reg_strb.intr_block_rf.notif_cmd_done_intr_count_incr_r = cpuif_req_masked & (cpuif_addr == 'ha10);
    end
    assign decoded_req = cpuif_req_masked;
    assign decoded_req_is_wr = cpuif_req_is_wr;
    assign decoded_wr_data = cpuif_wr_data;
    assign cpuif_wr_ack = decoded_req & decoded_req_is_wr;
    assign cpuif_wr_err = '0;
    typedef struct packed{
        struct packed{
            struct packed{
                logic [31:0] next;
                logic load_next;
            } IV;
        } [4-1:0]DOE_IV;
        struct packed{
            struct packed{
                logic [1:0] next;
                logic load_next;
            } CMD;
            struct packed{
                logic [4:0] next;
                logic load_next;
            } DEST;
        } DOE_CTRL;
        struct packed{
            struct packed{
                logic next;
                logic load_next;
            } READY;
            struct packed{
                logic next;
                logic load_next;
            } VALID;
            struct packed{
                logic next;
                logic load_next;
            } DEOBF_SECRETS_CLEARED;
        } DOE_STATUS;
        struct packed{
            struct packed{
                struct packed{
                    logic next;
                    logic load_next;
                } error_en;
                struct packed{
                    logic next;
                    logic load_next;
                } notif_en;
            } global_intr_en_r;
            struct packed{
                struct packed{
                    logic next;
                    logic load_next;
                } error0_en;
                struct packed{
                    logic next;
                    logic load_next;
                } error1_en;
                struct packed{
                    logic next;
                    logic load_next;
                } error2_en;
                struct packed{
                    logic next;
                    logic load_next;
                } error3_en;
            } error_intr_en_r;
            struct packed{
                struct packed{
                    logic next;
                    logic load_next;
                } notif_cmd_done_en;
            } notif_intr_en_r;
            struct packed{
                struct packed{
                    logic next;
                    logic load_next;
                } agg_sts;
            } error_global_intr_r;
            struct packed{
                struct packed{
                    logic next;
                    logic load_next;
                } agg_sts;
            } notif_global_intr_r;
            struct packed{
                struct packed{
                    logic next;
                    logic load_next;
                } error0_sts;
                struct packed{
                    logic next;
                    logic load_next;
                } error1_sts;
                struct packed{
                    logic next;
                    logic load_next;
                } error2_sts;
                struct packed{
                    logic next;
                    logic load_next;
                } error3_sts;
            } error_internal_intr_r;
            struct packed{
                struct packed{
                    logic next;
                    logic load_next;
                } notif_cmd_done_sts;
            } notif_internal_intr_r;
            struct packed{
                struct packed{
                    logic next;
                    logic load_next;
                } error0_trig;
                struct packed{
                    logic next;
                    logic load_next;
                } error1_trig;
                struct packed{
                    logic next;
                    logic load_next;
                } error2_trig;
                struct packed{
                    logic next;
                    logic load_next;
                } error3_trig;
            } error_intr_trig_r;
            struct packed{
                struct packed{
                    logic next;
                    logic load_next;
                } notif_cmd_done_trig;
            } notif_intr_trig_r;
            struct packed{
                struct packed{
                    logic [31:0] next;
                    logic load_next;
                    logic incrthreshold;
                    logic incrsaturate;
                } cnt;
            } error0_intr_count_r;
            struct packed{
                struct packed{
                    logic [31:0] next;
                    logic load_next;
                    logic incrthreshold;
                    logic incrsaturate;
                } cnt;
            } error1_intr_count_r;
            struct packed{
                struct packed{
                    logic [31:0] next;
                    logic load_next;
                    logic incrthreshold;
                    logic incrsaturate;
                } cnt;
            } error2_intr_count_r;
            struct packed{
                struct packed{
                    logic [31:0] next;
                    logic load_next;
                    logic incrthreshold;
                    logic incrsaturate;
                } cnt;
            } error3_intr_count_r;
            struct packed{
                struct packed{
                    logic [31:0] next;
                    logic load_next;
                    logic incrthreshold;
                    logic incrsaturate;
                } cnt;
            } notif_cmd_done_intr_count_r;
            struct packed{
                struct packed{
                    logic next;
                    logic load_next;
                    logic decrthreshold;
                    logic underflow;
                } pulse;
            } error0_intr_count_incr_r;
            struct packed{
                struct packed{
                    logic next;
                    logic load_next;
                    logic decrthreshold;
                    logic underflow;
                } pulse;
            } error1_intr_count_incr_r;
            struct packed{
                struct packed{
                    logic next;
                    logic load_next;
                    logic decrthreshold;
                    logic underflow;
                } pulse;
            } error2_intr_count_incr_r;
            struct packed{
                struct packed{
                    logic next;
                    logic load_next;
                    logic decrthreshold;
                    logic underflow;
                } pulse;
            } error3_intr_count_incr_r;
            struct packed{
                struct packed{
                    logic next;
                    logic load_next;
                    logic decrthreshold;
                    logic underflow;
