assign kv_key_read_ctrl_reg.pcr_hash_extend = hwif_out.HMAC384_KV_RD_KEY_CTRL.pcr_hash_extend.value;
assign kv_key_read_ctrl_reg.read_entry = hwif_out.HMAC384_KV_RD_KEY_CTRL.read_entry.value;
assign kv_key_read_ctrl_reg.read_en = hwif_out.HMAC384_KV_RD_KEY_CTRL.read_en.value;
assign kv_block_read_ctrl_reg.rsvd = '0;
assign kv_block_read_ctrl_reg.pcr_hash_extend = hwif_out.HMAC384_KV_RD_BLOCK_CTRL.pcr_hash_extend.value;
assign kv_block_read_ctrl_reg.read_entry = hwif_out.HMAC384_KV_RD_BLOCK_CTRL.read_entry.value;
assign kv_block_read_ctrl_reg.read_en = hwif_out.HMAC384_KV_RD_BLOCK_CTRL.read_en.value;
assign kv_write_ctrl_reg.rsvd = '0;
assign kv_write_ctrl_reg.write_dest_vld[0] = hwif_out.HMAC384_KV_WR_CTRL.hmac_key_dest_valid.value;
assign kv_write_ctrl_reg.write_dest_vld[1] = hwif_out.HMAC384_KV_WR_CTRL.hmac_block_dest_valid.value;
assign kv_write_ctrl_reg.write_dest_vld[2] = hwif_out.HMAC384_KV_WR_CTRL.sha_block_dest_valid.value;
assign kv_write_ctrl_reg.write_dest_vld[3] = hwif_out.HMAC384_KV_WR_CTRL.ecc_pkey_dest_valid.value;
assign kv_write_ctrl_reg.write_dest_vld[4] = hwif_out.HMAC384_KV_WR_CTRL.ecc_seed_dest_valid.value;
assign kv_write_ctrl_reg.write_dest_vld[5] = hwif_out.HMAC384_KV_WR_CTRL.ecc_msg_dest_valid.value;
