    .din    (sram_wdata    ),
    .ecc_out(sram_wdata_ecc)
);
initial assert(DATA_W == 32) else
    $error("%m::rvecc_encode supports 32-bit data width; must change SRAM ECC implementation to support DATA_W = %d", DATA_W);
