            field_storage.mbox_dataout.dataout.value <= 'h0;
        end else if(field_combo.mbox_dataout.dataout.load_next) begin
            field_storage.mbox_dataout.dataout.value <= field_combo.mbox_dataout.dataout.next;
        end
    end
    assign hwif_out.mbox_dataout.dataout.value = field_storage.mbox_dataout.dataout.value;
    assign hwif_out.mbox_dataout.dataout.swacc = decoded_reg_strb.mbox_dataout && !decoded_req_is_wr;
    always_comb begin
        automatic logic [0:0] next_c = field_storage.mbox_execute.execute.value;
        automatic logic load_next_c = '0;
        if(decoded_reg_strb.mbox_execute && decoded_req_is_wr && hwif_in.valid_requester) begin  
            next_c = decoded_wr_data[0:0];
            load_next_c = '1;
        end else if(hwif_in.mbox_execute.execute.hwclr) begin  
            next_c = '0;
            load_next_c = '1;
        end
        field_combo.mbox_execute.execute.next = next_c;
        field_combo.mbox_execute.execute.load_next = load_next_c;
    end
    always_ff @(posedge clk or negedge hwif_in.cptra_rst_b) begin
        if(~hwif_in.cptra_rst_b) begin
            field_storage.mbox_execute.execute.value <= 'h0;
        end else if(field_combo.mbox_execute.execute.load_next) begin
            field_storage.mbox_execute.execute.value <= field_combo.mbox_execute.execute.next;
        end
    end
    assign hwif_out.mbox_execute.execute.value = field_storage.mbox_execute.execute.value;
    always_comb begin
        automatic logic [3:0] next_c = field_storage.mbox_status.status.value;
        automatic logic load_next_c = '0;
        if(decoded_reg_strb.mbox_status && decoded_req_is_wr && hwif_in.valid_receiver) begin  
            next_c = decoded_wr_data[3:0];
            load_next_c = '1;
        end else if(hwif_in.mbox_status.status.hwclr) begin  
            next_c = '0;
            load_next_c = '1;
        end
        field_combo.mbox_status.status.next = next_c;
        field_combo.mbox_status.status.load_next = load_next_c;
    end
    always_ff @(posedge clk or negedge hwif_in.cptra_rst_b) begin
        if(~hwif_in.cptra_rst_b) begin
            field_storage.mbox_status.status.value <= 'h0;
        end else if(field_combo.mbox_status.status.load_next) begin
            field_storage.mbox_status.status.value <= field_combo.mbox_status.status.next;
        end
    end
    assign hwif_out.mbox_status.status.value = field_storage.mbox_status.status.value;
    always_comb begin
        automatic logic [0:0] next_c = field_storage.mbox_status.ecc_single_error.value;
        automatic logic load_next_c = '0;
        if(!field_storage.mbox_execute.execute.value) begin  
            next_c = field_storage.mbox_execute.execute.value;
            load_next_c = '1;
        end else if(hwif_in.mbox_status.ecc_single_error.hwset) begin  
            next_c = '1;
            load_next_c = '1;
        end
        field_combo.mbox_status.ecc_single_error.next = next_c;
        field_combo.mbox_status.ecc_single_error.load_next = load_next_c;
    end
    always_ff @(posedge clk or negedge hwif_in.cptra_rst_b) begin
        if(~hwif_in.cptra_rst_b) begin
            field_storage.mbox_status.ecc_single_error.value <= 'h0;
        end else if(field_combo.mbox_status.ecc_single_error.load_next) begin
            field_storage.mbox_status.ecc_single_error.value <= field_combo.mbox_status.ecc_single_error.next;
        end
    end
    assign hwif_out.mbox_status.ecc_single_error.value = field_storage.mbox_status.ecc_single_error.value;
    always_comb begin
        automatic logic [0:0] next_c = field_storage.mbox_status.ecc_double_error.value;
        automatic logic load_next_c = '0;
        if(!field_storage.mbox_execute.execute.value) begin  
            next_c = field_storage.mbox_execute.execute.value;
            load_next_c = '1;
        end else if(hwif_in.mbox_status.ecc_double_error.hwset) begin  
            next_c = '1;
            load_next_c = '1;
        end
        field_combo.mbox_status.ecc_double_error.next = next_c;
        field_combo.mbox_status.ecc_double_error.load_next = load_next_c;
    end
    always_ff @(posedge clk or negedge hwif_in.cptra_rst_b) begin
        if(~hwif_in.cptra_rst_b) begin
            field_storage.mbox_status.ecc_double_error.value <= 'h0;
        end else if(field_combo.mbox_status.ecc_double_error.load_next) begin
            field_storage.mbox_status.ecc_double_error.value <= field_combo.mbox_status.ecc_double_error.next;
        end
    end
    assign hwif_out.mbox_status.ecc_double_error.value = field_storage.mbox_status.ecc_double_error.value;
    always_comb begin
        automatic logic [2:0] next_c = field_storage.mbox_status.mbox_fsm_ps.value;
        automatic logic load_next_c = '0;
        if(1) begin  
            next_c = hwif_in.mbox_status.mbox_fsm_ps.next;
            load_next_c = '1;
        end
        field_combo.mbox_status.mbox_fsm_ps.next = next_c;
        field_combo.mbox_status.mbox_fsm_ps.load_next = load_next_c;
    end
    always_ff @(posedge clk or negedge hwif_in.cptra_rst_b) begin
        if(~hwif_in.cptra_rst_b) begin
            field_storage.mbox_status.mbox_fsm_ps.value <= 'h0;
        end else if(field_combo.mbox_status.mbox_fsm_ps.load_next) begin
            field_storage.mbox_status.mbox_fsm_ps.value <= field_combo.mbox_status.mbox_fsm_ps.next;
        end
    end
    assign hwif_out.mbox_status.mbox_fsm_ps.value = field_storage.mbox_status.mbox_fsm_ps.value;
    always_comb begin
        automatic logic [0:0] next_c = field_storage.mbox_status.soc_has_lock.value;
        automatic logic load_next_c = '0;
        if(1) begin  
            next_c = hwif_in.mbox_status.soc_has_lock.next;
            load_next_c = '1;
        end
        field_combo.mbox_status.soc_has_lock.next = next_c;
        field_combo.mbox_status.soc_has_lock.load_next = load_next_c;
    end
    always_ff @(posedge clk or negedge hwif_in.cptra_rst_b) begin
        if(~hwif_in.cptra_rst_b) begin
            field_storage.mbox_status.soc_has_lock.value <= 'h0;
        end else if(field_combo.mbox_status.soc_has_lock.load_next) begin
            field_storage.mbox_status.soc_has_lock.value <= field_combo.mbox_status.soc_has_lock.next;
        end
    end
    assign hwif_out.mbox_status.soc_has_lock.value = field_storage.mbox_status.soc_has_lock.value;
    always_comb begin
        automatic logic [0:0] next_c = field_storage.mbox_unlock.unlock.value;
        automatic logic load_next_c = '0;
        if(decoded_reg_strb.mbox_unlock && decoded_req_is_wr && !(hwif_in.soc_req)) begin  
            next_c = decoded_wr_data[0:0];
            load_next_c = '1;
        end else if(1) begin  
            next_c = '0;
            load_next_c = '1;
        end
        field_combo.mbox_unlock.unlock.next = next_c;
        field_combo.mbox_unlock.unlock.load_next = load_next_c;
    end
    always_ff @(posedge clk or negedge hwif_in.cptra_rst_b) begin
        if(~hwif_in.cptra_rst_b) begin
            field_storage.mbox_unlock.unlock.value <= 'h0;
        end else if(field_combo.mbox_unlock.unlock.load_next) begin
            field_storage.mbox_unlock.unlock.value <= field_combo.mbox_unlock.unlock.next;
        end
    end
    assign hwif_out.mbox_unlock.unlock.value = field_storage.mbox_unlock.unlock.value;
    logic readback_err;
    logic readback_done;
    logic [31:0] readback_data;
    logic [9-1:0][31:0] readback_array;
    assign readback_array[0][0:0] = (decoded_reg_strb.mbox_lock && !decoded_req_is_wr) ? field_storage.mbox_lock.lock.value : '0;
    assign readback_array[0][31:1] = '0;
    assign readback_array[1][31:0] = (decoded_reg_strb.mbox_user && !decoded_req_is_wr) ? field_storage.mbox_user.user.value : '0;
    assign readback_array[2][31:0] = (decoded_reg_strb.mbox_cmd && !decoded_req_is_wr) ? field_storage.mbox_cmd.command.value : '0;
    assign readback_array[3][31:0] = (decoded_reg_strb.mbox_dlen && !decoded_req_is_wr) ? field_storage.mbox_dlen.length.value : '0;
    assign readback_array[4][31:0] = (decoded_reg_strb.mbox_datain && !decoded_req_is_wr) ? field_storage.mbox_datain.datain.value : '0;
    assign readback_array[5][31:0] = (decoded_reg_strb.mbox_dataout && !decoded_req_is_wr) ? field_storage.mbox_dataout.dataout.value : '0;
    assign readback_array[6][0:0] = (decoded_reg_strb.mbox_execute && !decoded_req_is_wr) ? field_storage.mbox_execute.execute.value : '0;
    assign readback_array[6][31:1] = '0;
    assign readback_array[7][3:0] = (decoded_reg_strb.mbox_status && !decoded_req_is_wr) ? field_storage.mbox_status.status.value : '0;
    assign readback_array[7][4:4] = (decoded_reg_strb.mbox_status && !decoded_req_is_wr) ? field_storage.mbox_status.ecc_single_error.value : '0;
    assign readback_array[7][5:5] = (decoded_reg_strb.mbox_status && !decoded_req_is_wr) ? field_storage.mbox_status.ecc_double_error.value : '0;
    assign readback_array[7][8:6] = (decoded_reg_strb.mbox_status && !decoded_req_is_wr) ? field_storage.mbox_status.mbox_fsm_ps.value : '0;
    assign readback_array[7][9:9] = (decoded_reg_strb.mbox_status && !decoded_req_is_wr) ? field_storage.mbox_status.soc_has_lock.value : '0;
    assign readback_array[7][31:10] = '0;
    assign readback_array[8][0:0] = (decoded_reg_strb.mbox_unlock && !decoded_req_is_wr) ? field_storage.mbox_unlock.unlock.value : '0;
    assign readback_array[8][31:1] = '0;
    always_comb begin
        automatic logic [31:0] readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr;
        readback_err = '0;
        readback_data_var = '0;
        for(int i=0; i<9; i++) readback_data_var |= readback_array[i];
        readback_data = readback_data_var;
    end
    assign cpuif_rd_ack = readback_done;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
module sha512_acc_top
    import soc_ifc_pkg::*;
    import sha512_acc_csr_pkg::*;   
  #(
    parameter DATA_WIDTH = 32
    )(
      input logic         clk,
      input logic         rst_b,
      input logic         cptra_pwrgood,
      input logic         req_dv,
      output logic        req_hold,
      input soc_ifc_req_t req_data,
      output logic [DATA_WIDTH-1:0] rdata,
      output logic        err,
      output logic sha_sram_req_dv,
      output logic [MBOX_ADDR_W-1:0] sha_sram_req_addr,
      input mbox_sram_resp_t sha_sram_resp,
      input logic sha_sram_hold,
      output logic error_intr,
      output logic notif_intr
    );
  localparam ADDR_NAME0           = 32'h00000000;
  localparam ADDR_NAME1           = 32'h00000004;
  localparam ADDR_VERSION0        = 32'h00000008;
  localparam ADDR_VERSION1        = 32'h0000000c;
  localparam ADDR_CTRL            = 32'h00000010;
  localparam CTRL_INIT_BIT        = 0;
  localparam CTRL_NEXT_BIT        = 1;
  localparam CTRL_MODE_LOW_BIT    = 2;
  localparam CTRL_MODE_HIGH_BIT   = 3;
  localparam CTRL_WORK_FACTOR_BIT = 7;
  localparam ADDR_STATUS          = 32'h00000018;
  localparam ADDR_WORK_FACTOR_NUM = 32'h00000020;
  localparam ADDR_BLOCK_START     = 32'h00000080;
  localparam ADDR_BLOCK_END       = 32'h000000ff;
  localparam ADDR_DIGEST_START    = 32'h00000100;
  localparam ADDR_DIGEST_END      = 32'h0000013f;
  localparam SHA512_ADDR_INTR_START    = 32'h00000800;
  localparam SHA512_ADDR_INTR_END      = 32'h00000BFC;
  localparam CORE_NAME0           = 32'h61327368;  
  localparam CORE_NAME1           = 32'h31322d35;  
  localparam CORE_VERSION0        = 32'h3830302e;  
  localparam CORE_VERSION1        = 32'h00000000;  
  localparam MODE_SHA_512_224     = 2'h0;
  localparam MODE_SHA_512_256     = 2'h1;
  localparam MODE_SHA_384         = 2'h2;
  localparam MODE_SHA_512         = 2'h3;
  localparam DEFAULT_WORK_FACTOR_NUM = 32'h000f0000;
  localparam DATA_NUM_BYTES = DATA_WIDTH / 8;
  localparam BLOCK_NO = 1024 / DATA_WIDTH;
  localparam BYTE_NO = 1024 / 8;
  localparam BLOCK_OFFSET_W = $clog2(BLOCK_NO);
  localparam BYTE_OFFSET_W = $clog2(1024/8);
  typedef enum logic [2:0] {
    SHA_IDLE    = 3'b000,
    SHA_BLOCK_0 = 3'b001,
    SHA_BLOCK_N = 3'b011,
    SHA_PAD0    = 3'b010,
    SHA_PAD1    = 3'b110,
    SHA_DONE    = 3'b100
  } sha_fsm_state_e;
  logic lock_set;
  logic datain_write;
  logic stall_write;
  logic execute_set;
  logic init_reg;
  logic next_reg;
  logic soc_has_lock;
  logic [1:0] mode;
  logic [1:0] sha_mode;
  logic streaming_mode;
  logic mailbox_mode;
  logic [BYTE_OFFSET_W-1:0] num_bytes_data;
  logic extra_pad_block_required;
  logic [MBOX_ADDR_W:0] mbox_rdptr;
  logic [MBOX_ADDR_W-1:0] mbox_start_addr, mbox_end_addr;
  logic mbox_read_to_end;
  logic mbox_ptr_round_up;
  logic mbox_read_en;
  logic mbox_read_done;
  logic mbox_block_we;
  sha_fsm_state_e sha_fsm_ps, sha_fsm_ns;
  logic arc_SHA_IDLE_SHA_BLOCK_0;
  logic arc_SHA_BLOCK_0_SHA_BLOCK_N;
  logic arc_SHA_BLOCK_0_SHA_PAD0;
  logic arc_SHA_BLOCK_N_SHA_BLOCK_N;
  logic arc_SHA_BLOCK_N_SHA_PAD0;
  logic arc_SHA_PAD0_SHA_PAD1;
  logic arc_SHA_PAD0_SHA_DONE;
  logic arc_SHA_PAD1_SHA_DONE;
  logic arc_IDLE;
  logic mbox_mode_block_we;
  logic stream_mode_block_we;
  logic block_we;
  logic mbox_mode_last_dword_wr;
  logic stream_mode_last_dword_wr;
  logic last_dword_wr;
  logic block_full;
  logic [BLOCK_OFFSET_W:0] block_wptr;
  logic [DATA_NUM_BYTES-1:0][7:0] mbox_rdata;
  logic [DATA_WIDTH-1:0] block_wdata;
  logic [0:BLOCK_NO-1][DATA_WIDTH-1:0] block_reg,block_reg_nxt;
  logic [0:BYTE_NO-1][7:0] block_reg_nxt_pad;
  logic [1023:0] pad_mask;
  logic [127:0] pad_length;
  logic [0:15][31:0] digest_reg;
  logic              digest_valid_reg;
  sha512_acc_csr__in_t hwif_in;
  sha512_acc_csr__out_t hwif_out;
  logic read_error, write_error;
  logic              core_ready;
  logic              core_ready_q;
  logic [15:0][31:0] core_digest;
  logic              core_digest_valid;
  logic              core_digest_valid_q;
  logic zeroize_pulse;
  assign req_hold = stall_write;
  assign err = read_error | write_error;
  assign zeroize_pulse = hwif_out.CONTROL.ZEROIZE.value;
  sha512_core core(
                   .clk(clk),
                   .reset_n(rst_b),
                   .zeroize(zeroize_pulse),
                   .init_cmd(init_reg),
                   .next_cmd(next_reg),
                   .mode(sha_mode),
                   .work_factor(1'b0),
                   .work_factor_num(32'b0),
                   .block_msg(block_reg),
                   .ready(core_ready),
                   .digest(core_digest),
                   .digest_valid(core_digest_valid)
                  );
always_comb core_ready_q = core_ready & ~(init_reg | next_reg);
always_comb core_digest_valid_q = core_digest_valid & ~(init_reg | next_reg);
  always_ff @(posedge clk or negedge rst_b) begin : sha_regs
    if (!rst_b) begin
      digest_reg <= '0;
      digest_valid_reg <= '0;
      init_reg <= '0;
      next_reg <= '0;
    end
    else begin
      init_reg <= arc_SHA_BLOCK_0_SHA_BLOCK_N | arc_SHA_BLOCK_0_SHA_PAD0; 
      next_reg <= arc_SHA_BLOCK_N_SHA_BLOCK_N | arc_SHA_BLOCK_N_SHA_PAD0 | arc_SHA_PAD0_SHA_PAD1;
      digest_valid_reg <= core_digest_valid;
      if (core_digest_valid & ~digest_valid_reg)
        digest_reg <= core_digest;
    end
  end  
  always_comb hwif_in.USER.USER.next = req_data.user;
  always_comb lock_set = ~hwif_out.LOCK.LOCK.value & hwif_out.LOCK.LOCK.swmod & ~req_data.write;
  always_comb hwif_in.lock_set = lock_set;
  always_comb hwif_in.valid_user = hwif_out.LOCK.LOCK.value & ((~soc_has_lock & ~req_data.soc_req) |
                                                                (soc_has_lock & req_data.soc_req & (req_data.user == hwif_out.USER.USER.value)));
  always_comb hwif_in.soc_req = req_data.soc_req;
  always_comb mode = hwif_out.MODE.MODE.value;
  always_comb sha_mode = mode[0] ? MODE_SHA_512 : MODE_SHA_384;
  always_comb streaming_mode = ~mode[1];
  always_comb mailbox_mode = mode[1];
  always_comb datain_write = hwif_in.valid_user & hwif_out.DATAIN.DATAIN.swmod;
  always_comb execute_set = hwif_out.EXECUTE.EXECUTE.value;
  always_comb block_full = block_wptr[BLOCK_OFFSET_W];
  always_comb mbox_mode_last_dword_wr = mbox_mode_block_we & (block_wptr == (BLOCK_NO-1));
  always_comb stream_mode_last_dword_wr = stream_mode_block_we & (block_wptr == (BLOCK_NO-1));
  always_comb last_dword_wr = block_we & (block_wptr == (BLOCK_NO-1));
  always_comb mbox_read_en = mailbox_mode & ~mbox_read_done & !sha_sram_hold & (~(mbox_mode_last_dword_wr | block_full) | core_ready);
  always_comb sha_sram_req_dv = mbox_read_en;
  always_comb sha_sram_req_addr = mbox_rdptr[MBOX_ADDR_W-1:0];
  always_comb stall_write = datain_write & block_full;
  always_comb mbox_mode_block_we = (mailbox_mode & mbox_block_we);
  always_comb stream_mode_block_we = (streaming_mode & datain_write & ~stall_write);
  always_comb block_we = mbox_mode_block_we | stream_mode_block_we;
  always_comb begin
    for (int b=0; b<DATA_NUM_BYTES; b++) begin
      mbox_rdata[b] = hwif_out.MODE.ENDIAN_TOGGLE.value ? sha_sram_resp.rdata.data[b*8 +: 8] :  
                                                          sha_sram_resp.rdata.data[(DATA_NUM_BYTES-1-b)*8 +: 8];  
    end
  end
  always_comb block_wdata = ({DATA_WIDTH{streaming_mode}} & req_data.wdata) | 
                            ({DATA_WIDTH{mailbox_mode}} & mbox_rdata);
  always_ff @(posedge clk or negedge rst_b) begin : api_regs
    if (~rst_b) begin
      sha_fsm_ps    <= SHA_IDLE;
      soc_has_lock  <= '0;
      block_wptr    <= '0;
      mbox_rdptr    <= '0;
      mbox_block_we <= '0;
      block_reg     <= '0;
    end
    else begin
      sha_fsm_ps   <= sha_fsm_ns;
      soc_has_lock <= (hwif_in.lock_set & req_data.soc_req) ? '1 : '0;
      block_wptr <= (arc_SHA_BLOCK_0_SHA_BLOCK_N | arc_SHA_BLOCK_N_SHA_BLOCK_N | arc_IDLE) ? '0 :
                    block_we                                                               ? block_wptr + 'd1 : 
                                                                                             block_wptr;
      mbox_rdptr <= arc_SHA_IDLE_SHA_BLOCK_0 & mailbox_mode ? {1'b0,mbox_start_addr} :
                    mbox_read_en                            ? mbox_rdptr + 'd1 :
                                                              mbox_rdptr;
      mbox_block_we <= mbox_read_en;
      for (int dword = 0; dword < BLOCK_NO; dword++) begin
        block_reg[dword] <= block_we & (block_wptr[BLOCK_OFFSET_W-1:0] == dword) ? block_wdata : block_reg_nxt[dword];
      end
    end
  end
  assign num_bytes_data = hwif_out.DLEN.LENGTH.value[BYTE_OFFSET_W-1:0];
  assign extra_pad_block_required = (num_bytes_data >= 'd111);
  always_comb begin : sha_padding_logic
    pad_mask = '1;
    pad_mask = pad_mask << (1024-(num_bytes_data*8));
    pad_length = {{($bits(pad_length)-32){1'b0}}, hwif_out.DLEN.LENGTH.value} << 3;
    if (~extra_pad_block_required & (arc_SHA_BLOCK_0_SHA_PAD0 | arc_SHA_BLOCK_N_SHA_PAD0)) begin
      block_reg_nxt_pad = block_reg & pad_mask;
      block_reg_nxt_pad[num_bytes_data] = 8'h80;
      block_reg_nxt_pad[112:127] = pad_length;
    end
    else if (extra_pad_block_required & (arc_SHA_BLOCK_0_SHA_PAD0 | arc_SHA_BLOCK_N_SHA_PAD0)) begin
      block_reg_nxt_pad = block_reg & pad_mask;
      block_reg_nxt_pad[num_bytes_data] = 8'h80;
    end
    else if (arc_SHA_PAD0_SHA_PAD1) begin
      block_reg_nxt_pad = '0;
      block_reg_nxt_pad[112:127] = pad_length;
    end
    else begin
      block_reg_nxt_pad = block_reg;
    end
    block_reg_nxt = block_reg_nxt_pad;
  end
  always_comb mbox_start_addr = hwif_out.START_ADDRESS.ADDR.value[MBOX_ADDR_W-1:0];
  always_comb mbox_ptr_round_up = (|hwif_out.DLEN.LENGTH.value[1:0]);
  always_comb {mbox_read_to_end, mbox_end_addr} = mbox_ptr_round_up ? mbox_start_addr + (hwif_out.DLEN.LENGTH.value>>2) + 'd1 : 
                                                                      mbox_start_addr + (hwif_out.DLEN.LENGTH.value>>2);
  always_comb mbox_read_done = (sha_fsm_ps == SHA_IDLE) | ~mailbox_mode | 
                               (~mbox_read_to_end & mbox_rdptr[MBOX_ADDR_W-1:0] == mbox_end_addr) | 
                               (mbox_read_to_end & mbox_rdptr[MBOX_ADDR_W]);
  always_comb arc_IDLE = ~hwif_out.LOCK.LOCK.value;
  always_comb arc_SHA_IDLE_SHA_BLOCK_0 = (sha_fsm_ps == SHA_IDLE) & (
                                         (streaming_mode & datain_write) |
                                         (mailbox_mode & execute_set));
  always_comb arc_SHA_BLOCK_0_SHA_BLOCK_N = (sha_fsm_ps == SHA_BLOCK_0) & (last_dword_wr | block_full) & core_ready_q;
  always_comb arc_SHA_BLOCK_N_SHA_BLOCK_N = (sha_fsm_ps == SHA_BLOCK_N) & (last_dword_wr | block_full) & core_ready_q;
  always_comb arc_SHA_BLOCK_0_SHA_PAD0 = (sha_fsm_ps == SHA_BLOCK_0) & ~arc_SHA_BLOCK_0_SHA_BLOCK_N &
