    .a_y    ( a_omega_buf         ),  
    .b_x    ( b_gamma1_q          ),  
    .b_y    ( b_omega_buf         ),  
    .a_x_q  ( a_gamma1_qq         ),  
    .a_y_q  ( a_omega_buf_q       ),  
    .b_x_q  ( b_gamma1_qq         ),  
    .b_y_q  ( b_omega_buf_q       ),  
    .z_0    ( prd_3_i[5:4]        ),  
    .z_1    ( prd_3_i[7:6]        ),  
    .a_q    ( a_gamma_inv[1:0]    ),  
    .b_q    ( b_gamma_inv[1:0]    ),  
