  );
  logic [3:0] b_gamma0_omega_prd3;
  aes_dom_dep_mul_gf2pn #(
    .NPower      ( 2           ),
    .Pipeline    ( PipelineMul ),
    .PreDomIndep ( 1'b0        )
  ) u_aes_dom_mul_omega_gamma0 (
    .clk_i  ( clk_i               ),
    .rst_ni ( rst_ni              ),
    .we_i   ( we_i[1]             ),
    .a_x    ( a_omega_buf         ),  
    .a_y    ( a_gamma0_q          ),  
    .b_x    ( b_omega_buf         ),  
    .b_y    ( b_gamma0_q          ),  
    .a_x_q  ( a_omega_buf_q       ),  
    .a_y_q  ( a_gamma0_qq         ),  
    .b_x_q  ( b_omega_buf_q       ),  
    .b_y_q  ( b_gamma0_qq         ),  
    .z_0    ( prd_3_i[1:0]        ),  
    .z_1    ( prd_3_i[3:2]        ),  
    .a_q    ( a_gamma_inv[3:2]    ),  
    .b_q    ( b_gamma_inv[3:2]    ),  
    .prd_o  ( b_gamma0_omega_prd3 )   
  );
  assign prd_3_o = {b_gamma1_omega_prd3, b_gamma0_omega_prd3};
