        .in_ready_no           ( sp_in_ready[i]           ),  
        .out_valid_no          ( sp_out_valid[i]          ),  
        .out_ready_ni          ( sp_out_ready[i]          ),  
        .cfg_valid_i           ( cfg_valid_i              ),
        .op_i                  ( op_i                     ),
        .key_len_i             ( key_len_i                ),
        .crypt_ni              ( sp_crypt[i]              ),  
        .dec_key_gen_ni        ( sp_dec_key_gen[i]        ),  
        .prng_reseed_i         ( prng_reseed_i            ),
        .key_clear_i           ( key_clear_i              ),
