      .clk_i   (  clk_i   ),                           
      .rst_ni  (  rst_ni ),                           
      .state_i ( blk_enc_state_d     ),                           
      .state_o ( blk_enc_state_q     )                            
    );                                                
  localparam int OutBlkStateWidth = 6;
  typedef enum logic [OutBlkStateWidth-1:0] {
    AckIdle = 6'b110110,
    Load    = 6'b110001,
    Shift   = 6'b001001,
    OBError = 6'b011100
  } outblk_state_e;
  outblk_state_e outblk_state_d, outblk_state_q;
    prim_sparse_fsm_flop #(                           
      .StateEnumT(outblk_state_e),                            
      .Width($bits(outblk_state_e)),                          
      .ResetValue($bits(outblk_state_e)'(AckIdle)),          
      .EnableAlertTriggerSVA( 1)  
    ) u_outblk_state_regs (                                        
      .clk_i   (  clk_i   ),                           
      .rst_ni  (  rst_ni ),                           
      .state_i ( outblk_state_d     ),                           
      .state_o ( outblk_state_q     )                            
    );                                                
  always_ff @(posedge clk_i or negedge rst_ni)
    if (!rst_ni) begin
      interate_ctr_q     <= '0;
      concat_ctr_q       <= '0;
      concat_outblk_q    <= '0;
      concat_ccmd_q      <= '0;
      concat_inst_id_q   <= '0;
    end else begin
      interate_ctr_q     <= interate_ctr_d;
      concat_ctr_q       <= concat_ctr_d;
      concat_outblk_q    <= concat_outblk_d;
      concat_ccmd_q      <= concat_ccmd_d;
      concat_inst_id_q   <= concat_inst_id_d;
    end  
  prim_fifo_sync #(
    .Width(UpdReqFifoWidth),
    .Pass(0),
    .Depth(UpdReqFifoDepth),
