    .rst_ni  (rst_ni),
    .we     (err_code_test_gated_we),
    .wd     (err_code_test_wd),
    .de     (1'b0),
    .d      ('0),
    .qe     (err_code_test_flds_we[0]),
    .q      (reg2hw.err_code_test.q),
    .ds     (),
    .qs     (err_code_test_qs)
