               (addr_hit[13] & (|(CSRNG_PERMIT[13] & ~reg_be))) |
               (addr_hit[14] & (|(CSRNG_PERMIT[14] & ~reg_be))) |
               (addr_hit[15] & (|(CSRNG_PERMIT[15] & ~reg_be))) |
               (addr_hit[16] & (|(CSRNG_PERMIT[16] & ~reg_be)))));
