    always_comb ahb_lite_resp_disable[8]    = 1'b0;
    always_comb ahb_lite_resp_disable[9]     = 1'b0;
    always_comb ahb_lite_resp_disable[10] = 1'b0;
    always_comb ahb_lite_resp_disable[11]    = 1'b0;
    always_comb ahb_lite_resp_disable[12]    = iccm_lock & responder_inst[12].hwrite;
