    intr[12 -1]          = sha256_notif_intr;
    intr[13   -1]          = qspi_error_intr;
    intr[14   -1]          = qspi_notif_intr;
    intr[15   -1]          = uart_error_intr;
    intr[16   -1]          = uart_notif_intr;
    intr[17    -1]          = i3c_error_intr;
    intr[18    -1]          = i3c_notif_intr;
    intr[19-1]          = soc_ifc_error_intr;
    intr[20-1]          = soc_ifc_notif_intr;
    intr[21    -1]          = sha_error_intr;
    intr[22    -1]          = sha_notif_intr;
    intr[NUM_INTR-1:22]  = '0;
end
